window.ENGLISH_CARDS = [{"kind":"phrase","front":"play it by ear","meaning":"走一步看一步；根据情况调整（不一定完全没计划）","example":"We can decide where to eat later. Let's play it by ear."},{"kind":"phrase","front":"a close call","meaning":"险些出事；差一点就……","example":"I nearly missed the train. That was a close call."},{"kind":"phrase","front":"put a damper on something","meaning":"给心情、兴致、计划泼冷水","example":"The rain put a damper on our weekend plans."},{"kind":"phrase","front":"get carried away","meaning":"一时上头；做过头","example":"I got carried away and spent way too much."},{"kind":"phrase","front":"be on the fence (about)","meaning":"对某事犹豫不决","example":"I'm still on the fence about joining the trip."},{"kind":"phrase","front":"come in handy","meaning":"派上用场","example":"A power bank might come in handy."},{"kind":"phrase","front":"work around something","meaning":"想办法克服限制／变通处理","example":"We can work around your schedule."},{"kind":"phrase","front":"catch someone off guard","meaning":"让人措手不及","example":"His question caught me off guard."},{"kind":"phrase","front":"call it a day","meaning":"收工；今天到此为止","example":"We're exhausted. Let's call it a day."},{"kind":"phrase","front":"wing it","meaning":"不做充分准备，临场发挥","example":"I wouldn't wing it for a job interview."},{"kind":"phrase","front":"a rough outline / a rough plan","meaning":"大致框架；粗略计划","example":"I just need a rough plan, not a detailed itinerary."},{"kind":"phrase","front":"high-stakes","meaning":"事关重大的；风险较高的","example":"I prepare carefully for high-stakes situations."},{"kind":"phrase","front":"take someone's word for it","meaning":"因为某人这么说就相信","example":"I wouldn't just take his word for it."},{"kind":"phrase","front":"more nuanced than ...","meaning":"比……更有细微差别","example":"My approach to planning is more nuanced than that."},{"kind":"phrase","front":"micromanage / micromanagement","meaning":"事无巨细地控制","example":"I like planning, but not micromanagement."},{"kind":"phrase","front":"a brutal uphill climb","meaning":"一段非常折磨人的上坡","example":"The first two kilometres were a brutal uphill climb."},{"kind":"phrase","front":"the trail levels out","meaning":"山路变平缓","example":"After the steep section, the trail levels out."},{"kind":"phrase","front":"I've come this far, so I might as well ...","meaning":"都已经走到这了，索性……","example":"I've come this far, so I might as well finish."},{"kind":"phrase","front":"I didn't come all this way just to ...","meaning":"大老远来这儿可不是为了……","example":"I didn't come all this way just to turn back."},{"kind":"phrase","front":"breathtaking views","meaning":"美得令人屏息的风景","example":"The views from the ridge were breathtaking."},{"kind":"phrase","front":"settle in / settle into a rhythm","meaning":"渐渐适应／进入节奏","example":"It takes me a while to settle into a rhythm."},{"kind":"phrase","front":"feel drawn to nature","meaning":"自然而然被大自然吸引","example":"Even people who don't hike may feel drawn to nature."},{"kind":"phrase","front":"let my mind wander","meaning":"任思绪自由飘荡","example":"On long walks, I just let my mind wander."},{"kind":"phrase","front":"switch off","meaning":"让脑子暂时从工作和烦恼中抽离","example":"Being outdoors helps me switch off."},{"kind":"phrase","front":"get something off your chest","meaning":"把憋在心里的事说出来","example":"It's nice to get things off your chest."},{"kind":"phrase","front":"bottle things up","meaning":"把情绪压在心里","example":"You don't have to bottle everything up."},{"kind":"phrase","front":"vent (to someone)","meaning":"向某人倾诉、发牢骚","example":"Sometimes I just need to vent to a friend."},{"kind":"phrase","front":"bring people closer","meaning":"让彼此关系更近","example":"Going through a tough experience can bring people closer."},{"kind":"phrase","front":"a low-pressure opener","meaning":"没有压力的开场白","example":"“Beautiful day, isn't it?” is a low-pressure opener."},{"kind":"phrase","front":"keep to myself","meaning":"喜欢自己待着，不太主动社交","example":"I usually keep to myself when I travel."},{"kind":"phrase","front":"drain someone's energy","meaning":"消耗某人精力","example":"Big social events can drain my energy."},{"kind":"phrase","front":"be open to ...","meaning":"对……持开放态度","example":"I enjoy solo hiking, but I'm open to a chat."},{"kind":"sentence","front":"I'm not the kind of person who needs every little detail planned out.","meaning":"","example":""},{"kind":"sentence","front":"Especially if it's something that takes up a lot of time.","meaning":"","example":""},{"kind":"sentence","front":"I'd read up on the trail and check where it's safe to stay overnight.","meaning":"","example":""},{"kind":"sentence","front":"He'd need to know my fitness level and how active I normally am.","meaning":"","example":""},{"kind":"sentence","front":"The thought of hiking at 4,500 metres put a damper on my excitement.","meaning":"","example":""},{"kind":"sentence","front":"A lot of things can go wrong at high altitude.","meaning":"","example":""},{"kind":"sentence","front":"The first two kilometres are a brutal uphill climb.","meaning":"","example":""},{"kind":"sentence","front":"Every hike I've done has felt worth it in the end.","meaning":"","example":""},{"kind":"sentence","front":"The more trails you hike, the more similar the scenery can start to feel.","meaning":"","example":""},{"kind":"sentence","front":"I've seen just about every kind of landscape.","meaning":"","example":""},{"kind":"sentence","front":"I can just let my mind wander without any interruptions.","meaning":"","example":""},{"kind":"sentence","front":"You can complain freely without being judged.","meaning":"","example":""},{"kind":"sentence","front":"You don't have to bottle everything up or deal with those feelings on your own.","meaning":"","example":""},{"kind":"sentence","front":"When you both vent about how exhausting the hike is, it can bring you closer.","meaning":"","example":""},{"kind":"sentence","front":"I'm an introvert, and there usually aren't many people on those trails.","meaning":"","example":""},{"kind":"sentence","front":"I'd go up to them and say hi.","meaning":"","example":""},{"kind":"paragraph","front":"I'm an INTJ, and I definitely prefer having some kind of plan. I don't need a minute-by-minute schedule, but I'm not a big fan of last-minute decisions either, especially when something takes up a whole day or more. If it's just a short, straightforward hike at low altitude, I'm happy to be flexible. But for a multi-day hike or anything at high altitude, I wouldn't just wing it. I'd read up on the route, check the weather, and make sure I know what I'm getting into.","meaning":"","example":""},{"kind":"paragraph","front":"One thing I've noticed is that some hikes are toughest right at the beginning. I remember a trail where the first two kilometres were a brutal uphill climb. Once I'd got through that section, the path levelled out and the rest was much more straightforward. Even when I feel exhausted, I sometimes tell myself, “I've come this far, so I might as well keep going.” Most of the time, the views turn out to be breathtaking, and I feel it was worth the effort. Of course, I'd turn back if conditions got genuinely dangerous.","meaning":"","example":""},{"kind":"paragraph","front":"I love hiking for the scenery, but it's not just about the views. What I really enjoy is the sense of freedom. Sometimes I completely switch off and just take in what's around me. Other times, I let my mind wander. I might think about work, the stock market, or random things that have been bothering me, but I still feel relaxed. Out there, nobody's constantly interrupting me or handing me another task. I can think about whatever I want, at my own pace.","meaning":"","example":""},{"kind":"paragraph","front":"I'm quite introverted, so most of the time I'd rather hike on my own. I like being able to go at my own pace and enjoy the peace and quiet. But that doesn't mean I don't want to talk to anyone. If I run into another hiker, I'm happy to say hi, and sometimes I might strike up a conversation. Something simple like “Beautiful view, isn't it?” is enough. I like having the freedom to chat when I feel like it, without feeling obligated to socialize the whole time.","meaning":"","example":""},{"kind":"sentence","front":"I've been swamped lately.","meaning":"","example":""},{"kind":"phrase","front":"clear up","meaning":"天气转晴；澄清（视语境）","example":"It looks like it'll clear up this afternoon."},{"kind":"phrase","front":"cool / chilly / cold / freezing / bitterly cold","meaning":"凉快／冷飕飕／冷／冷得厉害／刺骨的冷","example":"It's chilly this morning, but not freezing."},{"kind":"phrase","front":"push something back","meaning":"把某项安排往后推","example":"Can we push our meeting back by an hour?"},{"kind":"phrase","front":"raise ethical concerns","meaning":"引发诚信/伦理上的担忧（略正式但常用）","example":"Making up experience on a CV raises ethical concerns."},{"kind":"phrase","front":"exaggerate my experience","meaning":"夸大工作经验","example":"I'd rather be honest than exaggerate my experience."},{"kind":"phrase","front":"keep up an image / keep up appearances","meaning":"维持某种形象／做表面功夫","example":"I'd have to keep up an image that isn't really me."},{"kind":"phrase","front":"if it comes out / comes to light","meaning":"如果事情曝光；被发现","example":"If it comes out, it could have serious consequences."},{"kind":"phrase","front":"take time off","meaning":"请假、休假","example":"I need to take time off for exams."},{"kind":"phrase","front":"spread out throughout the semester","meaning":"分散在整个学期","example":"My exams are spread out throughout the semester."},{"kind":"phrase","front":"commit to a full-time role","meaning":"承诺投入全职岗位","example":"I can't commit to a full-time role right now."},{"kind":"phrase","front":"walk away","meaning":"选择退出，不再继续","example":"Sometimes it's better to walk away."},{"kind":"phrase","front":"jeopardize something","meaning":"使某事面临风险","example":"I don't want to jeopardize my degree."},{"kind":"phrase","front":"at the end of the day","meaning":"说到底，归根结底","example":"At the end of the day, finishing my degree comes first."},{"kind":"phrase","front":"gross me out","meaning":"让我恶心、反胃","example":"Finding the toilet unflushed really grosses me out."},{"kind":"phrase","front":"give someone the benefit of the doubt","meaning":"暂时往好处想，相信对方不是故意的（建议延伸）","example":"I gave him the benefit of the doubt at first."},{"kind":"phrase","front":"my first sip / take a sip","meaning":"第一口（饮品）／抿一口","example":"The moment I took my first sip, I knew I hated it."},{"kind":"phrase","front":"spit it out / spat it out","meaning":"把东西吐出来／过去式","example":"The coffee tasted awful, so I spat it out."},{"kind":"phrase","front":"put someone off something","meaning":"使某人对某物失去兴趣、产生反感","example":"The smell puts me off coffee."},{"kind":"phrase","front":"the aftertaste","meaning":"余味，回味","example":"I can't stand the bitter aftertaste."},{"kind":"phrase","front":"gentle and comforting","meaning":"温和、让人舒服安心","example":"Tea feels gentler and more comforting to me."},{"kind":"phrase","front":"oats / oatmeal / peanut butter","meaning":"燕麦／燕麦粥／花生酱","example":"I usually have oats or toast with peanut butter."},{"kind":"phrase","front":"the idea of working full-time puts me off","meaning":"“全职工作这个念头让我反感”","example":"It's not just one company; the idea of working full-time puts me off."},{"kind":"phrase","front":"job security is shaky","meaning":"工作稳定性不可靠","example":"Even well-paid jobs can feel insecure when job security is shaky."},{"kind":"phrase","front":"a decent salary / decent pay","meaning":"还不错的工资","example":"A decent salary doesn't necessarily mean a comfortable life."},{"kind":"phrase","front":"be protective of one's time","meaning":"很珍惜、保护自己的时间","example":"Younger workers may be more protective of their free time."},{"kind":"phrase","front":"put food on the table","meaning":"养家糊口；满足基本生存需要","example":"In the past, many people worked simply to put food on the table."},{"kind":"phrase","front":"feel empty / unfulfilled","meaning":"精神空虚／缺乏成就或满足感","example":"You can have enough money and still feel unfulfilled."},{"kind":"phrase","front":"make things worse / intensify","meaning":"加剧、使情况恶化（前者更口语）","example":"Social media can make that pressure worse."},{"kind":"phrase","front":"the goalposts keep moving","meaning":"标准不断抬高，永远不够","example":"Every time people earn more, the goalposts seem to keep moving."},{"kind":"phrase","front":"barrier to entry","meaning":"入门门槛","example":"The cost of equipment is a barrier to entry for skiing."},{"kind":"phrase","front":"have a mind of your own","meaning":"有自己的主见（建议延伸）","example":"You can be influenced by others and still have a mind of your own."},{"kind":"phrase","front":"travel burnout","meaning":"旅行疲劳、旅行倦怠","example":"I think I've got a bit of travel burnout."},{"kind":"phrase","front":"mentally drained / mentally exhausted","meaning":"精神疲惫","example":"After so many trips, I felt mentally drained."},{"kind":"phrase","front":"diminishing returns","meaning":"边际体验递减（生活、商业都能用）","example":"After seeing so many similar churches, there are diminishing returns."},{"kind":"phrase","front":"magnificent / grand","meaning":"宏伟壮观／富丽堂皇","example":"The cathedral was absolutely magnificent."},{"kind":"phrase","front":"intricate stone carvings","meaning":"精巧繁复的石雕","example":"I was amazed by the intricate stone carvings."},{"kind":"phrase","front":"underwhelming","meaning":"没预想中惊艳；让人失望","example":"The next church felt a bit underwhelming."},{"kind":"phrase","front":"raise the bar","meaning":"抬高标准或期待","example":"Seeing Rome's churches really raised the bar for me."},{"kind":"phrase","front":"blur together","meaning":"在记忆里逐渐混成一片","example":"After a while, all those old towns start to blur together."},{"kind":"phrase","front":"stand out","meaning":"格外突出、令人印象深刻","example":"That little chapel actually stood out from the others."},{"kind":"phrase","front":"tick things off a list","meaning":"为打卡而打卡、逐项完成清单","example":"I don't want to spend every trip just ticking things off a list."},{"kind":"phrase","front":"get the most out of something","meaning":"尽量获得最多收获","example":"I used to try to get the most out of every trip."},{"kind":"phrase","front":"wasn't particularly aware of it at the time","meaning":"当时没有特别清晰地意识到","example":"I wasn't particularly aware of the fatigue at the time."},{"kind":"phrase","front":"much more noticeable now","meaning":"现在更加明显、能清楚感知","example":"That feeling is much more noticeable now."},{"kind":"phrase","front":"on short notice","meaning":"提前通知时间很短","example":"I don't mind changes on short notice if there's a good reason."},{"kind":"phrase","front":"question the friendship","meaning":"质疑这段友谊是否值得维持","example":"It makes me question the friendship."},{"kind":"phrase","front":"stay friends with someone","meaning":"继续和某人做朋友","example":"I'm not sure I want to stay friends with someone who's always late."},{"kind":"phrase","front":"not worth the hassle","meaning":"不值得这样折腾","example":"Constantly rearranging plans isn't worth the hassle."},{"kind":"sentence","front":"A few things about the offer are bothering me.","meaning":"","example":""},{"kind":"sentence","front":"It raises some serious ethical concerns.","meaning":"","example":""},{"kind":"sentence","front":"It's tempting, but not tempting enough to give up my degree for.","meaning":"","example":""},{"kind":"sentence","front":"It clashes with my exam schedule.","meaning":"","example":""},{"kind":"sentence","front":"I can't commit to a full-time position right now.","meaning":"","example":""},{"kind":"sentence","front":"I'd be happy to stay in touch about future opportunities.","meaning":"","example":""},{"kind":"sentence","front":"I kept giving him the benefit of the doubt.","meaning":"","example":""},{"kind":"sentence","front":"The moment I took my first sip, I spat it out.","meaning":"","example":""},{"kind":"sentence","front":"Even the smell of coffee puts me off.","meaning":"","example":""},{"kind":"sentence","front":"Why are so many young people fed up with work?","meaning":"","example":""},{"kind":"sentence","front":"We're far more productive than ever before.","meaning":"","example":""},{"kind":"sentence","front":"Other churches might feel underwhelming by comparison.","meaning":"","example":""},{"kind":"sentence","front":"I wasn't particularly aware of that feeling at the time.","meaning":"","example":""},{"kind":"sentence","front":"After a while, they all start to blur together.","meaning":"","example":""},{"kind":"sentence","front":"I'd start wondering whether I even want to stay friends.","meaning":"","example":""},{"kind":"paragraph","front":"I had an interview for a software testing position, and the salary was pretty tempting. But a couple of things bothered me. For one thing, they wanted me to make up experience on my CV and keep up that story once I started working. That's a huge red flag for me. On top of that, the full-time schedule clashes with my exams. At the end of the day, it's just not worth jeopardizing my degree. So I've decided to turn the offer down. I'd rather be upfront about it and stay in touch in case something more suitable comes up later.","meaning":"","example":""},{"kind":"paragraph","front":"Thanks, but coffee really isn't for me. I gave it a try once in Finland, and the moment I took my first sip, I wanted to spit it out. I don't know if it's the bitterness, the smell, or the aftertaste, but the whole thing puts me off. Tea is different, though. Even when it's bitter, I find it gentler and more comforting. So if you've got tea, I'd happily have that instead.","meaning":"","example":""},{"kind":"paragraph","front":"I don't think young people necessarily hate doing anything productive. A lot of us just feel that full-time jobs take up too much of our lives, and we don't always get enough in return. We're more productive than ever, yet the goalposts keep moving. Once you can put food on the table, you start wanting experiences, hobbies, and more freedom. And social media can make that pressure even worse. So there's this contradiction: you need money to enjoy your free time, but you have to give up so much of that time to earn it.","meaning":"","example":""},{"kind":"paragraph","front":"I traveled to a lot of places in a short period, and I think I got a bit burned out. I still love traveling, but planning another trip sometimes feels like work. I've seen so many magnificent churches and intricate stone carvings in Italy that smaller churches can feel a little underwhelming by comparison. It's not that they're bad. It's just that the bar has been raised. After a while, old towns and city halls start to blur together. Looking back, I wasn't particularly aware of how tired I was at the time, but it's much more noticeable now. I'd rather slow down and choose a few places that genuinely interest me.","meaning":"","example":""},{"kind":"phrase","front":"cook most of my meals myself","meaning":"大部分饭自己做","example":"I cook most of my meals myself, whether they’re quick and easy or more time-consuming."},{"kind":"phrase","front":"get the timing right","meaning":"掌握烹饪时机","example":"It’s tricky to get the timing right when everything goes into one pot."},{"kind":"phrase","front":"save the quick-cooking ingredients for last","meaning":"易熟食材最后放","example":"I cook the vegetables that take longer first and save the spinach for last."},{"kind":"phrase","front":"turn mushy","meaning":"煮得软烂、糊软","example":"If you add spinach too early, it can turn mushy."},{"kind":"phrase","front":"follow a recipe / improvise","meaning":"按菜谱做／临场发挥","example":"Sometimes I follow a recipe, but often I just improvise."},{"kind":"phrase","front":"time-consuming","meaning":"耗时的","example":"Cooking a full meal can be surprisingly time-consuming."},{"kind":"phrase","front":"limit my options","meaning":"限制选择","example":"Having only an electric pot really limits my options."},{"kind":"phrase","front":"cookware / kitchenware / kitchen utensils","meaning":"锅具／厨房用品总称／厨用工具","example":"Cleaning my cookware and kitchen utensils afterward takes time."},{"kind":"phrase","front":"stove / stovetop","meaning":"炉灶／炉灶表面","example":"I don’t have a stove or an oven in my dorm room."},{"kind":"phrase","front":"clean up / the cleanup","meaning":"清理（动词）／收拾清洗（名词）","example":"The cleanup sometimes takes longer than the cooking."},{"kind":"phrase","front":"a cold draft (UK: draught)","meaning":"从窗户透进来的冷风","example":"When I open the window in winter, a cold draft comes in."},{"kind":"phrase","front":"a window seal / a gap in the frame","meaning":"窗户密封条／窗框缝隙","example":"A gap in the window frame can let cold air in."},{"kind":"phrase","front":"noise coming through thin walls","meaning":"穿过薄墙传来的噪音","example":"I can hear noise coming through the thin walls."},{"kind":"phrase","front":"heavy footsteps / chair scrapes","meaning":"沉重脚步声／椅子拖刮声","example":"My neighbor’s heavy footsteps and chair scrapes are distracting."},{"kind":"phrase","front":"a low-frequency thump","meaning":"低频咚咚震动声","example":"The most annoying sound is a low-frequency thump."},{"kind":"phrase","front":"mask the noise","meaning":"用另一种声音掩盖噪音","example":"I want some background noise that can mask the thumping."},{"kind":"phrase","front":"a steady background sound","meaning":"持续稳定的背景声音","example":"A steady background sound can be less distracting than sudden thumps."},{"kind":"phrase","front":"mentally exhausted / mentally drained","meaning":"精神疲惫的／心力交瘁的","example":"After practicing English for an hour, I felt mentally drained."},{"kind":"phrase","front":"go over mistakes","meaning":"逐一检查、讲解错误","example":"The lecturer went over the mistakes and explained how to fix them."},{"kind":"phrase","front":"weigh my options","meaning":"权衡各种选项","example":"I have to weigh my options whenever work overlaps with class."},{"kind":"phrase","front":"my time would be better spent elsewhere","meaning":"我的时间花在别处可能更值得","example":"I can’t help but wonder if my time would be better spent elsewhere."},{"kind":"phrase","front":"get something out of something","meaning":"从某事中获得价值／收获","example":"It’s frustrating when I don’t feel I’m getting much out of a class."},{"kind":"phrase","front":"put in the effort / get little in return","meaning":"付出努力／回报很少","example":"I’m willing to put in the effort, but sometimes I get little in return."},{"kind":"phrase","front":"get my point across","meaning":"把意思表达清楚","example":"I can usually get my point across, even if my grammar isn’t perfect."},{"kind":"phrase","front":"have a good command of English","meaning":"很好地掌握英语","example":"I want to have a better command of everyday English."},{"kind":"phrase","front":"the flow of a conversation","meaning":"对话的流畅度／节奏","example":"Too much hesitation can interrupt the flow of a conversation."},{"kind":"phrase","front":"dig a little deeper","meaning":"进一步深入讨论","example":"We can dig a little deeper without turning it into a lecture."},{"kind":"phrase","front":"only scratch the surface","meaning":"仅触及表面","example":"Today we only scratched the surface of the subject."},{"kind":"phrase","front":"take a more academic approach","meaning":"从更偏学术的角度入手","example":"Sometimes I want to take a slightly more academic approach."},{"kind":"phrase","front":"the underlying mechanisms","meaning":"背后的机制","example":"I’m interested in the psychological mechanisms underlying our choices."},{"kind":"phrase","front":"refer to a study / cite an article","meaning":"提及研究／引用论文","example":"In casual conversation, we can refer to a study without formally citing it."},{"kind":"phrase","front":"draw on research","meaning":"借助研究结果支撑观点","example":"You can draw on research without using academic language all the time."},{"kind":"phrase","front":"choose every word with absolute precision","meaning":"字斟句酌、准确选词","example":"I don’t need to choose every word with absolute precision."},{"kind":"phrase","front":"social comparison","meaning":"社会比较","example":"Social comparison existed long before social media."},{"kind":"phrase","front":"in relative rather than absolute terms","meaning":"用相对而非绝对标准衡量","example":"We often judge our success in relative rather than absolute terms."},{"kind":"phrase","front":"the highlight reel of someone’s life","meaning":"他人生活的高光剪辑","example":"Social media mostly shows the highlight reels of other people’s lives."},{"kind":"phrase","front":"hedonic adaptation","meaning":"享乐适应：逐渐习惯生活改善","example":"Hedonic adaptation may help explain why new comforts stop feeling special."},{"kind":"phrase","front":"set unrealistic expectations","meaning":"制造不切实际的期待","example":"Constant exposure to luxury lifestyles can set unrealistic expectations."},{"kind":"phrase","front":"fuel envy and dissatisfaction","meaning":"加剧羡慕与不满","example":"Unfair comparisons can fuel envy and dissatisfaction."},{"kind":"phrase","front":"measure your self-worth by ...","meaning":"用……衡量自我价值","example":"It’s exhausting to measure your self-worth by other people’s achievements."},{"kind":"phrase","front":"the rat race / be caught up in the rat race","meaning":"激烈的竞争生活／陷入内卷竞争","example":"Some people feel caught up in the rat race from an early age."},{"kind":"phrase","front":"get ahead","meaning":"出人头地、取得优势","example":"Everyone seems to be trying to get ahead."},{"kind":"phrase","front":"wear someone down","meaning":"使人长期疲惫、消磨意志","example":"Constant comparison can wear people down over time."},{"kind":"phrase","front":"attach too much importance to ...","meaning":"过度看重……","example":"Why do we attach so much importance to being better off than others?"},{"kind":"phrase","front":"compare ourselves with others","meaning":"将自己与他人比较","example":"We’ve been comparing ourselves with others since we were very young."},{"kind":"phrase","front":"exceptional lifestyles as the norm","meaning":"把极少数人的优越生活当作常态","example":"The problem starts when we treat exceptional lifestyles as the norm."},{"kind":"sentence","front":"We’ve been comparing ourselves with others since we were young.","meaning":"","example":""},{"kind":"paragraph","front":"I cook most of my meals myself, but I've started eating out once or twice a week. I did the math, and it doesn't cost me that much. The biggest issue is that I live in a dorm and only have an electric pot in my room. Without a proper stove, my options are limited. Even making noodles takes planning because I have to add the ingredients in the right order. Sometimes I wonder whether spending so much time cooking is really worth the hassle.","meaning":"","example":""},{"kind":"paragraph","front":"My neighbor's heavy footsteps and chair scrapes come through the thin walls as low-frequency thumps. I open my window to let in background noise that masks them, but in winter a cold draft comes in too.","meaning":"","example":""},{"kind":"paragraph","front":"This morning, I practiced English for about an hour before going to class. I could tell I was making progress, but I still felt mentally exhausted. The lectures were even more frustrating because I couldn't always follow what the lecturer was saying. At the same time, I noticed that the rates on my delivery app had gone up. That made me think about the opportunity cost of staying in class. I know education matters, but I can't help wondering whether my time would sometimes be better spent elsewhere.","meaning":"","example":""},{"kind":"paragraph","front":"My main goal isn't to become a translator or use complicated academic language. I want to have a good command of everyday English so I can communicate naturally with people from different backgrounds. I can usually get my point across, but sometimes I struggle to find the right words. I don't mind making minor grammatical mistakes as long as they don't cause misunderstandings. What matters most to me is being able to go beyond small talk and have more in-depth conversations.","meaning":"","example":""},{"kind":"paragraph","front":"I think social comparison is part of human nature. Even before social media, people compared themselves with neighbors, classmates, and colleagues. Social media acts as an amplifier: now we can see the lifestyles of extremely wealthy people thousands of miles away. That can set unrealistic expectations and fuel envy and dissatisfaction. In my experience growing up in China, competition started early, with comparisons of grades and achievements. The goalposts kept moving, and it sometimes felt like the rat race would never end. I don't think competition is always harmful, but constantly measuring your self-worth against other people can be mentally exhausting.","meaning":"","example":""},{"kind":"phrase","front":"shake out your clothes","meaning":"把衣服抖开、甩一甩","example":"Give your clothes a good shake before hanging them up."},{"kind":"phrase","front":"hang them up to dry","meaning":"挂起来晾干","example":"Shake them out before you hang them up to dry."},{"kind":"phrase","front":"get all wrinkled","meaning":"变得皱巴巴","example":"They’ll get all wrinkled if you leave them in a pile."},{"kind":"phrase","front":"crumpled / wrinkled","meaning":"揉成一团、皱成一团 / 表面起褶皱","example":"The shirt was crumpled in my bag and came out wrinkled."},{"kind":"phrase","front":"walk towards each other","meaning":"相向而行；迎面走来","example":"We were walking towards each other along the pavement."},{"kind":"phrase","front":"walk past each other","meaning":"相向走过、擦肩而过","example":"We walked past each other without saying a word."},{"kind":"phrase","front":"almost bump into each other","meaning":"差点迎面撞上","example":"We almost bumped into each other at the doorway."},{"kind":"phrase","front":"leverage ...","meaning":"充分利用（常见于商业语境）","example":"Investors sometimes leverage their experience to spot opportunities."},{"kind":"phrase","front":"fall into a routine / be in a routine","meaning":"形成固定作息、进入规律","example":"I’ve fallen into a routine: breakfast, campus, study, repeat."},{"kind":"phrase","front":"my days blur together","meaning":"每天都差不多，日子混在一起","example":"I do similar things every day, so my days blur together."},{"kind":"phrase","front":"a repetitive routine","meaning":"重复性的日常","example":"My routine is repetitive, but I don’t mind it."},{"kind":"phrase","front":"a night owl","meaning":"夜猫子、晚间精力旺盛的人","example":"I’m definitely a night owl; I think more clearly at night."},{"kind":"phrase","front":"feel mentally alert","meaning":"头脑清醒、精神敏锐","example":"I feel much more mentally alert after sunset."},{"kind":"phrase","front":"my brain kicks into gear","meaning":"大脑开始进入状态","example":"It takes a while for my brain to kick into gear."},{"kind":"phrase","front":"get a second wind","meaning":"突然恢复精力","example":"I often get a second wind late at night."},{"kind":"phrase","front":"feel groggy","meaning":"刚睡醒昏沉","example":"I feel groggy for quite a while after waking up."},{"kind":"phrase","front":"take time to get going","meaning":"需要时间进入状态","example":"It takes me longer than average to get going in the morning."},{"kind":"phrase","front":"warm up mentally","meaning":"让头脑慢慢进入状态","example":"I need time to warm up mentally before doing difficult work."},{"kind":"phrase","front":"carve out some quiet time","meaning":"挤出、专门留出安静时间","example":"I’ve carved out a few hours to study without distractions."},{"kind":"phrase","front":"my mood goes downhill","meaning":"心情变差、一路下滑","example":"When the thumping starts, my mood goes downhill."},{"kind":"phrase","front":"heavy thuds / thumping","meaning":"沉重的咚咚声、撞击声","example":"Heavy thuds from next door make it hard to concentrate."},{"kind":"phrase","front":"crack the window open","meaning":"把窗户开一条缝","example":"I cracked the window open to let some air in."},{"kind":"phrase","front":"leave the window slightly open","meaning":"窗户留一条小缝","example":"I leave the window slightly open even when it’s cold."},{"kind":"phrase","front":"let some fresh air in","meaning":"让新鲜空气进来","example":"A little fresh air helps me stay awake."},{"kind":"phrase","front":"cut right through my jacket","meaning":"冷风穿透衣服、吹得透心凉","example":"The wind at eight in the morning cut right through my jacket."},{"kind":"phrase","front":"soak up some sunshine","meaning":"晒晒太阳、享受阳光","example":"I’m just sitting by the window, soaking up some sunshine."},{"kind":"phrase","front":"the radiator / the heating is on","meaning":"暖气片 / 暖气开着","example":"The heating is on, so the room gets warm quickly."},{"kind":"phrase","front":"feel drowsy","meaning":"昏昏欲睡","example":"An overheated room makes me feel drowsy."},{"kind":"phrase","front":"perk me up","meaning":"使我精神一振","example":"A little cool air perks me up."},{"kind":"phrase","front":"stay alert / clear-headed","meaning":"保持清醒 / 头脑清楚","example":"Fresh air helps me stay alert and clear-headed."},{"kind":"phrase","front":"the Wi-Fi keeps dropping out","meaning":"无线网络总是断连","example":"The university Wi-Fi keeps dropping out in the middle of calls."},{"kind":"phrase","front":"the connection cuts in and out","meaning":"网络连接时断时续","example":"The connection keeps cutting in and out."},{"kind":"phrase","front":"the Wi-Fi is unreliable / laggy","meaning":"无线网络不稳定 / 延迟很高","example":"It’s frustrating that the campus Wi-Fi is so unreliable."},{"kind":"phrase","front":"sound contradictory / paradoxical","meaning":"听起来矛盾 / 悖论式的","example":"It sounds paradoxical, but a small hassle can save time later."},{"kind":"phrase","front":"tension between two goals","meaning":"两个目标之间的张力与冲突","example":"There’s tension between maximizing efficiency and ensuring fairness."},{"kind":"phrase","front":"sacrifice some fairness for efficiency","meaning":"为提高效率牺牲一部分公平","example":"Improving efficiency can sometimes mean sacrificing some fairness."},{"kind":"phrase","front":"a turning point / a contrast","meaning":"转折点 / 对照转折关系","example":"Use “but” when the second clause introduces a genuine contrast."},{"kind":"phrase","front":"take a nosedive","meaning":"突然大跌、断崖式下跌","example":"The market took a nosedive over a short period."},{"kind":"phrase","front":"pull back / a pullback","meaning":"回撤、相对温和的调整","example":"A pullback sounds less dramatic than a plunge."},{"kind":"phrase","front":"weather the downturn","meaning":"挺过市场下行期","example":"My portfolio has weathered the downturn fairly well."},{"kind":"phrase","front":"take a hit / hold up well","meaning":"受到冲击 / 顶住压力","example":"The market took a hit, but my portfolio held up well."},{"kind":"phrase","front":"an investment portfolio / holdings","meaning":"投资组合 / 持仓","example":"A large part of my portfolio consists of U.S. holdings."},{"kind":"phrase","front":"a niche interest","meaning":"小众兴趣","example":"Stock investing is still a niche interest in my social circle."},{"kind":"phrase","front":"opposing views / a counterargument","meaning":"相反观点 / 反驳论据","example":"I’m happy to read opposing views if they’re well reasoned."},{"kind":"phrase","front":"back up a claim with evidence","meaning":"用证据支持观点","example":"People should back up their claims with reasoning, not emotion."},{"kind":"phrase","front":"feel self-conscious","meaning":"在意他人眼光而局促不安","example":"I sometimes feel self-conscious around strangers."},{"kind":"phrase","front":"feel neutral about ...","meaning":"对……既不紧张也不兴奋","example":"Sometimes I feel neutral about talking to classmates."},{"kind":"phrase","front":"socialize / be sociable","meaning":"参加社交、与人交往 / 善于交际","example":"I can socialize when I need to; I just don’t always want to."},{"kind":"phrase","front":"build a social network / network with people","meaning":"建立人际关系 / 社交拓展人脉","example":"Being introverted doesn’t mean I can’t network with people."},{"kind":"phrase","front":"social etiquette","meaning":"社交礼仪","example":"I usually follow social etiquette, even when I feel uncomfortable."},{"kind":"phrase","front":"leave early / leave abruptly","meaning":"提前离开 / 突然离场","example":"I’d feel awkward leaving early while everyone else stayed."},{"kind":"phrase","front":"show up / make it to the event","meaning":"到场 / 赶得上活动","example":"I’m not sure I can make it to the meeting."},{"kind":"phrase","front":"feel drained / drain my energy","meaning":"感到精疲力尽 / 耗尽我的精力","example":"Long social gatherings can drain my energy."},{"kind":"phrase","front":"enjoy my own company","meaning":"享受独处","example":"I enjoy my own company, reading or playing games."},{"kind":"phrase","front":"be on the fence about ...","meaning":"对……犹豫未决","example":"I’m still on the fence about ordering takeout."},{"kind":"phrase","front":"dry out","meaning":"失去水分，逐渐干掉","example":"The vegetables will dry out if I leave them too long."},{"kind":"phrase","front":"I’m not entirely sure what was in it","meaning":"我不太确定里面是什么","example":"I’m not entirely sure what was in the second burger."},{"kind":"phrase","front":"come with a sweet sauce","meaning":"配有甜酱","example":"One of the burgers came with a sweet sauce."},{"kind":"phrase","front":"not really to my taste","meaning":"不太合我的口味","example":"That sauce wasn’t really to my taste."},{"kind":"phrase","front":"too sweet for my liking","meaning":"对我而言太甜了","example":"The sauce was a bit too sweet for my liking."},{"kind":"phrase","front":"savory / savoury","meaning":"咸鲜口的（美/英拼写）","example":"I like both sweet and savory food, just not that combination."},{"kind":"phrase","front":"a large order of fries","meaning":"一大份薯条","example":"I had two chicken burgers and a large order of fries."},{"kind":"phrase","front":"plain broccoli","meaning":"不加调味的西兰花","example":"I usually eat plain broccoli to keep things simple."},{"kind":"phrase","front":"minced garlic / dice the garlic","meaning":"蒜末 / 把蒜切丁","example":"People often add minced garlic to vegetables."},{"kind":"phrase","front":"cook through / cook quickly","meaning":"熟透 / 熟得快","example":"Different ingredients take different amounts of time to cook through."},{"kind":"phrase","front":"the easiest / most effortless part","meaning":"最容易 / 最不费力的部分","example":"Boiling vegetables is the most effortless part of cooking."},{"kind":"phrase","front":"purchasing power","meaning":"购买力","example":"Groceries cost less back home, so I’d have more purchasing power."},{"kind":"phrase","front":"my money goes further","meaning":"同样的钱更经花","example":"My money would go a lot further in China."},{"kind":"phrase","front":"not much of a shopper","meaning":"不太爱购物的人","example":"I’m not much of a shopper, so I don’t miss shopping malls."},{"kind":"phrase","front":"not particularly materialistic","meaning":"物质欲望不强","example":"I’m not particularly materialistic, and I enjoy simple hobbies."},{"kind":"phrase","front":"my quality of life has taken a hit","meaning":"生活质量受到了影响","example":"My day-to-day quality of life has taken a hit in the dorm."},{"kind":"phrase","front":"day-to-day comfort / convenience","meaning":"日常舒适度 / 便利性","example":"I’ve given up some day-to-day comfort by moving abroad."},{"kind":"phrase","front":"keep my options open","meaning":"给未来保留选择空间","example":"I want to keep my options open for the future."},{"kind":"phrase","front":"a concrete benefit","meaning":"实实在在的好处","example":"Traveling around Europe is one concrete benefit of living here."},{"kind":"phrase","front":"historical and cultural attractions / sites","meaning":"历史与人文景点","example":"I’m not especially interested in historical and cultural sites."},{"kind":"phrase","front":"ancient ruins / historical remains","meaning":"古代遗迹 / 历史遗存","example":"Many museums display objects and remains from earlier periods."},{"kind":"phrase","front":"the Middle Ages / medieval history","meaning":"中世纪 / 中世纪历史","example":"I don’t always feel engaged by medieval history."},{"kind":"phrase","front":"have historical significance","meaning":"具有历史意义","example":"I know those places have historical significance."},{"kind":"phrase","front":"a must-see attraction","meaning":"必看、必去景点","example":"I sometimes feel pressure to visit every must-see attraction."},{"kind":"phrase","front":"go out of obligation, not interest","meaning":"出于义务而非兴趣去做","example":"Sometimes I visit museums out of obligation, not interest."},{"kind":"phrase","front":"feel uncomfortable skipping it","meaning":"跳过会觉得不踏实","example":"I’d feel uncomfortable skipping an important historical site."},{"kind":"phrase","front":"natural scenery / scenic landscapes","meaning":"自然风景 / 风景优美的景观","example":"Natural scenery appeals to me far more than old buildings."},{"kind":"phrase","front":"snow-capped mountains / blue seas","meaning":"雪山 / 蔚蓝的海","example":"I get excited by snow-capped mountains and blue seas."},{"kind":"phrase","front":"hiking trails / coastal landscapes","meaning":"徒步路线 / 海岸景观","example":"I love hiking trails and coastal landscapes."},{"kind":"phrase","front":"lift my mood / turn my mood around","meaning":"改善心情、使心情好转","example":"A beautiful landscape can lift my mood immediately."},{"kind":"phrase","front":"come alive","meaning":"一下子精神起来、变得活跃","example":"I seem to come alive when I reach a scenic viewpoint."},{"kind":"phrase","front":"rather than a “want,” it feels like a “should”","meaning":"不是想去，而是觉得应该去","example":"Visiting some museums feels more like a “should” than a “want.”"},{"kind":"sentence","front":"Give your clothes a good shake, or they’ll get all wrinkled.","meaning":"","example":""},{"kind":"sentence","front":"Two people are walking towards each other.","meaning":"","example":""},{"kind":"sentence","front":"I need somewhere quiet where nobody will interrupt me.","meaning":"","example":""},{"kind":"sentence","front":"A little hassle now makes the rest of the day easier.","meaning":"","example":""},{"kind":"sentence","front":"This draft doesn’t make me feel cold.","meaning":"","example":""},{"kind":"sentence","front":"There’s often a trade-off between efficiency and fairness.","meaning":"","example":""},{"kind":"sentence","front":"Stock investing is still a niche interest in my social circle.","meaning":"","example":""},{"kind":"sentence","front":"KFC is running a promotion today.","meaning":"","example":""},{"kind":"sentence","front":"The sweet sauce isn’t really to my taste.","meaning":"","example":""},{"kind":"sentence","front":"I have greater purchasing power.","meaning":"","example":""},{"kind":"sentence","front":"My quality of life has gone down.","meaning":"","example":""},{"kind":"sentence","front":"Natural scenery appeals to me much more.","meaning":"","example":""},{"kind":"paragraph","front":"My days are pretty repetitive. I wake up around the same time, eat roughly the same breakfast, and head to the same academic building. I'm not really a morning person, so getting out of bed can be a struggle. But the dorm is noisy, and I need somewhere I can focus. Walking over to the building is a small price to pay for a whole day of peace. Once I'm there, I can study at my own pace without anyone interrupting me.","meaning":"","example":""},{"kind":"paragraph","front":"I'm definitely a night owl. My brain seems to kick into gear later in the evening, and I can get a surprising amount done. In the morning, though, I feel groggy and need a while to get going. When the heating is on, the study room can get stuffy and make me drowsy. I usually crack the window open to let some fresh air in. Even if there's a slight draft, it perks me up and helps me stay alert.","meaning":"","example":""},{"kind":"paragraph","front":"The Chinese stock market has plunged recently, but my portfolio has held up relatively well and outperformed the index over that period. I tend to keep my investment decisions to myself. Investing is still a niche interest in my social circle, and I don't find it useful to debate stocks with people who only repeat their feelings. I'm happy to read opposing views, but I want to see clear reasoning and evidence. Information that's already priced in doesn't really give me an edge.","meaning":"","example":""},{"kind":"paragraph","front":"People sometimes assume I'm shy because I keep to myself. I can feel self-conscious in certain situations, but being introverted doesn't mean I can't socialize. It just means I enjoy my own company and need time to myself. When a conversation matters, I can take part. At parties, I usually follow social etiquette even if I'm not enjoying myself. That's partly why I prefer to decline invitations politely rather than leave early and feel awkward.","meaning":"","example":""},{"kind":"paragraph","front":"I was torn between cooking at home and getting KFC because there was a pretty good promotion on hot wings. The price was tempting, but I'd already had KFC the day before. I also had some broccoli in my room that was starting to turn yellow. So I was leaning towards cooking at home. I don't particularly enjoy plain broccoli, but boiling it is effortless: I just bring the water to a boil, add the broccoli, and wait a few minutes. The clean-up is easy too.","meaning":"","example":""},{"kind":"paragraph","front":"I'm not much of a shopper, so shopping malls and cinemas don't make much difference to me. Food and living conditions are another story. Back in China, my money would go further, and I'd have access to food that suits my taste. My quality of life has taken a hit in some day-to-day ways since I moved into a dorm. But living in Lithuania has also given me the opportunity to travel around Europe much more easily. I've visited around ten European countries, and the airfare alone would have made those trips more expensive from China. For now, I see it as a trade-off: less comfort in some areas, but more opportunities to broaden my horizons.","meaning":"","example":""},{"kind":"paragraph","front":"I've realized that I'm not as interested in historical and cultural sites as I once thought. I understand why ancient ruins, museums and medieval buildings matter to human civilization, and I sometimes feel obligated to visit them when I'm in a historic city. But that sense of duty isn't the same as genuine excitement. Natural scenery appeals to me much more. Snow-capped mountains, blue seas and hiking trails can lift my mood almost immediately. It's strange: I may feel tired after visiting several museums, but when I reach a beautiful natural landscape, I suddenly feel excited again. That reaction tells me a lot about what I really enjoy.","meaning":"","example":""},{"kind":"phrase","front":"I’m not really into + noun / -ing","meaning":"我不太喜欢……","example":"I’m not really into visiting museums."},{"kind":"phrase","front":"Even though + clause, main clause","meaning":"即使……仍然……","example":"Even though the market fell, my portfolio held up fairly well."},{"kind":"phrase","front":"A appeals to me much more than B","meaning":"A 比 B 更吸引我","example":"Natural scenery appeals to me much more than historical sites."},{"kind":"phrase","front":"I can’t help but + verb","meaning":"忍不住……","example":"I can’t help but wonder whether the experience is worth it."},{"kind":"phrase","front":"A has taken a hit, but ...","meaning":"A 受到冲击，但……","example":"My daily comfort has taken a hit, but I’ve gained other opportunities."},{"kind":"phrase","front":"A has outperformed B over that period","meaning":"A 在那段期间跑赢 B","example":"My portfolio has outperformed the index over that period."},{"kind":"phrase","front":"have the whole place to myself","meaning":"独占整个空间、几乎没人","example":"I had the whole study room to myself."},{"kind":"phrase","front":"upbeat","meaning":"轻快、积极的","example":"She stayed upbeat despite the bad weather."},{"kind":"phrase","front":"keep someone up","meaning":"让某人睡不着","example":"The noise kept me up all night."},{"kind":"phrase","front":"soaked / wet / damp / dry","meaning":"湿透／湿／潮湿／干燥","example":"My jacket was soaked after the hike, but my socks stayed dry."},{"kind":"phrase","front":"leak / spill / drip / drain / splatter","meaning":"漏／洒／滴／排走／飞溅","example":"Water started dripping from the pipe."},{"kind":"phrase","front":"ancient artifacts / ancient collections","meaning":"古代文物／古代藏品","example":"Museums put ancient artifacts on display."},{"kind":"phrase","front":"on display","meaning":"展出、陈列","example":"Is the original sculpture on display here?"},{"kind":"phrase","front":"a documentary","meaning":"纪录片","example":"I can learn a lot from books and documentaries."},{"kind":"phrase","front":"What can ... offer that ... can’t?","meaning":"……能提供什么……无法提供的？","example":"What can museums offer that books can’t?"},{"kind":"phrase","front":"see something in person","meaning":"亲眼看到","example":"Seeing a sculpture in person feels different from seeing a photo."},{"kind":"phrase","front":"the scale, texture and atmosphere","meaning":"尺度、质感与氛围","example":"A photo doesn’t always capture the scale and texture."},{"kind":"phrase","front":"an original / a replica","meaning":"原作／复制品","example":"The statue in the square is a replica, not the original."},{"kind":"phrase","front":"craftsmanship / attention to detail","meaning":"工艺水平／对细节的关注","example":"I was blown away by the craftsmanship and attention to detail."},{"kind":"phrase","front":"intricate / sophisticated","meaning":"精细复杂的／精妙复杂的","example":"The sculpture looks incredibly intricate."},{"kind":"phrase","front":"be blown away by","meaning":"被……深深震撼（口语）","example":"I was blown away by how detailed the sculpture was."},{"kind":"phrase","front":"be astonished by / in awe of","meaning":"惊叹于／对……心生敬畏","example":"I was genuinely astonished by the work."},{"kind":"phrase","front":"exceptional / world-class","meaning":"出类拔萃的／世界级的","example":"I’d make time for a museum with something exceptional on display."},{"kind":"phrase","front":"struggle to see the point of","meaning":"难以理解做某事的意义","example":"I struggle to see the point of visiting an ordinary museum."},{"kind":"phrase","front":"stay with someone","meaning":"在心中久久留存","example":"The feeling stays with me long after the hike."},{"kind":"phrase","front":"linger / a lingering feeling","meaning":"萦绕不散／余韵","example":"That sense of peace lingers for days."},{"kind":"phrase","front":"exhilarated","meaning":"畅快、兴奋不已","example":"I feel exhilarated when I reach an incredible viewpoint."},{"kind":"phrase","front":"invigorated","meaning":"精神振奋、充满活力","example":"I come back from the mountains feeling invigorated."},{"kind":"phrase","front":"uplifted / lift my spirits","meaning":"心情振奋／让我心情变好","example":"Those memories still lift my spirits."},{"kind":"phrase","front":"rejuvenated / refreshed","meaning":"焕然一新／恢复精神","example":"A few days outdoors leave me feeling refreshed."},{"kind":"phrase","front":"fulfilled / a sense of fulfillment","meaning":"充实、满足／成就满足感","example":"Hiking gives me a real sense of fulfillment."},{"kind":"phrase","front":"inspired / eager to","meaning":"受到激励／迫不及待想……","example":"Remembering the trip makes me eager to hike again."},{"kind":"phrase","front":"look back on / think back to","meaning":"回想、回顾","example":"Even months later, I look back on those hikes fondly."},{"kind":"phrase","front":"long for / crave","meaning":"渴望、向往","example":"When city life gets stressful, I long for the mountains."},{"kind":"phrase","front":"clear my head / reset","meaning":"让头脑清醒／重新调整状态","example":"Being outdoors helps me clear my head."},{"kind":"phrase","front":"subconsciously / deep down","meaning":"潜意识里／内心深处","example":"Deep down, I think we still feel connected to nature."},{"kind":"phrase","front":"consciously / without realizing it","meaning":"有意识地／不知不觉地","example":"We may feel that connection without realizing it."},{"kind":"phrase","front":"things to get done / responsibilities to deal with","meaning":"要完成的事／需要处理的责任","example":"There’s always something to worry about and things to get done."},{"kind":"phrase","front":"escape into nature / get away from it all","meaning":"到自然中暂时逃离／远离日常纷扰","example":"On weekends I sometimes want to get away from it all."},{"kind":"phrase","front":"the peace and quiet / the buzz of the city","meaning":"宁静／城市的热闹活力","example":"Some people enjoy the city’s buzz; others prefer the peace and quiet."},{"kind":"phrase","front":"be accustomed to / take for granted","meaning":"习惯于／视为理所当然","example":"People can take familiar surroundings for granted."},{"kind":"phrase","front":"be drawn to what is missing","meaning":"向往日常生活中缺少的东西","example":"We’re often drawn to whatever is missing from everyday life."},{"kind":"phrase","front":"it comes down to","meaning":"归根结底是……","example":"Maybe it comes down to what people feel is missing."},{"kind":"phrase","front":"raw data / unstructured data","meaning":"原始数据／非结构化数据","example":"Raw data isn’t always ready to analyze."},{"kind":"phrase","front":"be scattered across","meaning":"分散在各处","example":"Useful information can be scattered across different websites."},{"kind":"phrase","front":"collect / scrape / process data","meaning":"收集／抓取／处理数据","example":"Code can help you scrape, clean and process data."},{"kind":"phrase","front":"turn data into useful insights","meaning":"把数据转化为有用见解","example":"I want to turn messy data into useful insights."},{"kind":"phrase","front":"a skill gap / a missing piece","meaning":"技能短板／缺失的一环","example":"Programming was the missing piece in my previous work."},{"kind":"phrase","front":"identify and analyze requirements","meaning":"识别并分析需求","example":"Developers need to identify and analyze requirements."},{"kind":"phrase","front":"translate requirements into specifications","meaning":"将需求转化为软件规格说明","example":"You translate business requirements into technical specifications."},{"kind":"phrase","front":"design workflows / draw flowcharts","meaning":"设计工作流程／绘制流程图","example":"The team designs workflows before implementing the system."},{"kind":"phrase","front":"implement a solution / write the code","meaning":"实现解决方案／编写代码","example":"Finally, you implement the design in code."},{"kind":"phrase","front":"I initially thought ... but later realized ...","meaning":"起初以为……后来意识到……","example":"I initially thought it was all about coding, but later realized there was much more to it."},{"kind":"phrase","front":"take on freelance projects / small gigs","meaning":"承接自由职业项目／小单子","example":"Some freelancers take on small website projects."},{"kind":"phrase","front":"the going rate / charge for a project","meaning":"市场通常报价／项目收费","example":"The going rate for basic websites may be changing."},{"kind":"phrase","front":"disrupt the old paradigm","meaning":"打破旧有范式","example":"AI seems to be disrupting the old paradigm."},{"kind":"phrase","front":"rewrite the rules of the game","meaning":"改写游戏规则","example":"AI is rewriting the rules of the game."},{"kind":"phrase","front":"turn an industry upside down","meaning":"使行业发生天翻地覆的变化","example":"New technology can turn an industry upside down."},{"kind":"phrase","front":"the essentials / necessities","meaning":"生活必需品","example":"I don’t shop much; I mainly buy essentials."},{"kind":"phrase","front":"professional models / flattering angles","meaning":"专业模特／显好看的拍摄角度","example":"Brands use models and flattering camera angles."},{"kind":"phrase","front":"retouched / heavily edited photos","meaning":"修过图的／精修的照片","example":"Product photos can be heavily retouched."},{"kind":"phrase","front":"look amazing online / look different in person","meaning":"网上看着很棒／实物却不同","example":"The jacket looked amazing online but different in person."},{"kind":"phrase","front":"the fit is off","meaning":"版型不合适","example":"The material feels okay, but the fit is off."},{"kind":"phrase","front":"fall short of my expectations","meaning":"不符合我的期望","example":"The actual product fell short of my expectations."},{"kind":"phrase","front":"live up to the pictures / expectations","meaning":"达到图片／期待的效果","example":"The shirt didn’t live up to the product photos."},{"kind":"phrase","front":"shrug it off / let it go","meaning":"一笑置之／不再计较","example":"Usually I just shrug it off and move on."},{"kind":"phrase","front":"not worth ruining my day over","meaning":"不值得为此坏了一天心情","example":"A disappointing purchase isn’t worth ruining my day over."},{"kind":"phrase","front":"put me in a bad mood / get on my nerves","meaning":"使我心情变差／惹我心烦","example":"I won’t let one bad purchase put me in a bad mood."},{"kind":"sentence","front":"Seeing it in a film is completely different from standing in front of it.","meaning":"","example":""},{"kind":"sentence","front":"I was blown away by the David sculpture I saw in Florence.","meaning":"","example":""},{"kind":"sentence","front":"The statue in the square was a replica.","meaning":"","example":""},{"kind":"sentence","front":"How could an artist create something so sophisticated centuries ago?","meaning":"","example":""},{"kind":"sentence","front":"Even months later, those memories still lift my spirits.","meaning":"","example":""},{"kind":"sentence","front":"We aren’t always consciously aware of it.","meaning":"","example":""},{"kind":"sentence","front":"The whole atmosphere stays with me.","meaning":"","example":""},{"kind":"sentence","front":"It keeps drawing me back to that feeling.","meaning":"","example":""},{"kind":"sentence","front":"By contrast, they might be more drawn to city life.","meaning":"","example":""},{"kind":"sentence","front":"Some data is scattered across different websites.","meaning":"","example":""},{"kind":"sentence","front":"Use code throughout the process, from collecting data to analyzing it.","meaning":"","example":""},{"kind":"sentence","front":"Translate those requirements into detailed software specifications and designs.","meaning":"","example":""},{"kind":"sentence","front":"I initially thought coding was the core of the degree.","meaning":"","example":""},{"kind":"sentence","front":"Rates keep falling.","meaning":"","example":""},{"kind":"sentence","front":"Some freelancers might take on more projects thanks to AI.","meaning":"","example":""},{"kind":"sentence","front":"AI is disrupting the old paradigm and rewriting the rules of the game.","meaning":"","example":""},{"kind":"sentence","front":"They use professional models and heavily retouch the photos.","meaning":"","example":""},{"kind":"sentence","front":"They use flattering lighting and camera angles.","meaning":"","example":""},{"kind":"sentence","front":"The clothes don’t look the same on you as they do on the model.","meaning":"","example":""},{"kind":"sentence","front":"These clothes / these pieces of clothing ...","meaning":"","example":""},{"kind":"sentence","front":"It’s not worth wasting my time or ruining my mood over.","meaning":"","example":""},{"kind":"sentence","front":"A product this bad shouldn’t be sold to customers.","meaning":"","example":""},{"kind":"phrase","front":"Unless ..., I struggle to see the point of ...","meaning":"表达对特定活动价值的保留态度。","example":"Unless there’s something exceptional, I struggle to see the point of going."},{"kind":"phrase","front":"Seeing A is different from experiencing B.","meaning":"区分媒介体验与现场体验。","example":"Seeing a mountain in a video is different from being there."},{"kind":"phrase","front":"Even months later, I still ...","meaning":"长期效应。","example":"Even months later, those memories still lift my spirits."},{"kind":"phrase","front":"from A to B","meaning":"描述完整流程。","example":"I want to automate the process from collecting data to analyzing it."},{"kind":"phrase","front":"A is rewriting the rules of B.","meaning":"格局发生变化。","example":"AI is rewriting the rules of freelance software development."},{"kind":"phrase","front":"A looked ..., but when it arrived ...","meaning":"网购前后落差。","example":"The shirt looked great online, but when it arrived, the material felt cheap."},{"kind":"phrase","front":"It didn’t live up to ...","meaning":"现实低于预期。","example":"It didn’t live up to my expectations."},{"kind":"phrase","front":"I’ll ... if ..., but otherwise I’ll ...","meaning":"带条件的日常取舍。","example":"I’ll complain if the quality is terrible, but otherwise I’ll let it go."},{"kind":"paragraph","front":"I understand why people enjoy museums, and I know you can learn a lot from them. But if my main goal is to learn about history, I can usually get much of that information from books or documentaries. What I can’t get from a book is the feeling of standing in front of an original work and seeing its scale and craftsmanship in person. That’s why I’d definitely visit a museum with something truly exceptional on display. For an ordinary museum, though, I sometimes struggle to see what I’d get out of it.","meaning":"","example":""},{"kind":"paragraph","front":"When I was in Florence, I saw a replica of Michelangelo’s David in the square. Even though it wasn’t the original, I was still blown away by its scale and attention to detail. It’s hard to imagine someone creating something so sophisticated more than five hundred years ago. But I’m not really an art enthusiast, so for me the experience was mostly a moment of amazement rather than something that changed my interests.","meaning":"","example":""},{"kind":"paragraph","front":"For me, hiking is about more than beautiful scenery. It’s the whole atmosphere, especially that sense of freedom, that stays with me long after the trip. Even months later, thinking back to those moments still lifts my spirits and makes me eager to head out again. City life moves at such a fast pace that there’s always something to worry about or get done. Being out in nature gives me a chance to slow down and clear my head. Interestingly, someone who lives in a remote village might feel the opposite and be more drawn to city life. Maybe we’re often attracted to whatever is missing from our everyday lives.","meaning":"","example":""},{"kind":"paragraph","front":"I switched to software engineering because I wanted to combine my background in business analysis with programming. In my previous work, a lot of useful information was scattered across different websites, and it wasn’t always in a format I could analyze directly in Excel. I wanted to learn how to collect, clean and analyze that data more efficiently. But after starting the degree, I realized software engineering was much more than writing code. It also involved analyzing requirements, designing workflows and translating ideas into technical specifications. At the same time, AI is changing the way simple software projects are built, which makes me rethink what independent development might look like in the future.","meaning":"","example":""},{"kind":"paragraph","front":"I don’t buy much beyond the essentials. Sometimes clothes look amazing online because brands use professional models, flattering lighting and heavily edited photos. But when the item arrives, the fit might be off or the material might feel cheap. If the quality is truly unacceptable, I’d be annoyed and might leave a one-star review. Most of the time, though, I’d just shrug it off and avoid that shop in the future. A relatively small purchase isn’t worth wasting my time or ruining my mood over.","meaning":"","example":""},{"kind":"phrase","front":"buy the dip","meaning":"逢低买入","example":"Some investors I follow have started buying the dip."},{"kind":"phrase","front":"make a small purchase / make a small buy","meaning":"少量买入","example":"I made a small buy today, but it barely changed my allocation."},{"kind":"phrase","front":"a token purchase / a token buy","meaning":"象征性买入、极小规模买入","example":"It was more of a token purchase than a meaningful addition."},{"kind":"phrase","front":"a meaningful addition to my position","meaning":"对持仓有实质影响的加仓","example":"I don’t have enough spare cash to make a meaningful addition to my position."},{"kind":"phrase","front":"existing holdings","meaning":"现有持仓","example":"The purchase was tiny compared with my existing holdings."},{"kind":"phrase","front":"limited spare cash / limited dry powder","meaning":"可动用现金有限（dry powder 投资口语）","example":"With limited dry powder, I need to be selective."},{"kind":"phrase","front":"incremental purchases / buy in increments","meaning":"分批、小额地买入","example":"I’m building my position through incremental purchases."},{"kind":"phrase","front":"gradually build up a position","meaning":"逐步建立或增加仓位","example":"I’d rather gradually build up a position than rush in."},{"kind":"phrase","front":"step up my purchases / accelerate my buying","meaning":"加快买入速度、增加买入量","example":"If prices fall further, I might step up my purchases."},{"kind":"phrase","front":"commit more capital","meaning":"投入更多资金","example":"I’m hesitant to commit more capital without a clear reason."},{"kind":"phrase","front":"broad-market index funds","meaning":"宽基指数基金","example":"I’ve mainly been buying broad-market index funds."},{"kind":"phrase","front":"stock picking / pick individual stocks","meaning":"主动选股","example":"I’m avoiding stock picking while the whole market is under pressure."},{"kind":"phrase","front":"capture broad-market returns","meaning":"获得宽基市场表现（不保证收益）","example":"An index fund lets me capture the benchmark’s returns without choosing individual winners."},{"kind":"phrase","front":"sell-off","meaning":"抛售、下跌行情","example":"The sell-off has continued for another week."},{"kind":"phrase","front":"drawdown / peak-to-trough decline","meaning":"回撤、从高点到低点的跌幅","example":"A large drawdown doesn’t automatically make an asset cheap."},{"kind":"phrase","front":"pullback / correction / crash","meaning":"回调／较明显调整／崩盘（程度不同）","example":"This is more than a minor pullback, but a crash is a stronger word."},{"kind":"phrase","front":"a full-blown crash","meaning":"全面、严重的崩盘","example":"I hope the sell-off doesn’t turn into a full-blown crash."},{"kind":"phrase","front":"historically attractive valuations","meaning":"历史上较有吸引力的估值","example":"I look for historically attractive valuations rather than just large price declines."},{"kind":"phrase","front":"a convincing catalyst","meaning":"有说服力的催化因素","example":"I can’t identify a convincing catalyst for a sustained rebound."},{"kind":"phrase","front":"trigger a rebound / stage a rebound","meaning":"引发反弹／出现反弹","example":"Even a small improvement in sentiment could trigger a rebound."},{"kind":"phrase","front":"a sustained recovery","meaning":"持续性复苏或回升","example":"A short-lived bounce isn’t the same as a sustained recovery."},{"kind":"phrase","front":"turn sentiment around","meaning":"扭转市场情绪","example":"Better earnings could help turn sentiment around."},{"kind":"phrase","front":"selling pressure eases / selling pressure is exhausted","meaning":"卖压缓解／卖压衰竭","example":"Markets can rebound when selling pressure starts to ease."},{"kind":"phrase","front":"bargain hunters step in","meaning":"逢低买入者进场","example":"Bargain hunters sometimes step in after a steep decline."},{"kind":"phrase","front":"a bearish view / bearish voices","meaning":"看空观点／看空声音","example":"Even some bearish voices say valuations aren’t especially high."},{"kind":"phrase","front":"illustrate the severity of the sell-off","meaning":"说明抛售的严重程度","example":"I mentioned the drawdown to illustrate the severity of the sell-off, not to prove stocks are cheap."},{"kind":"phrase","front":"market-wide dislocation","meaning":"市场层面价格或定价出现明显偏离","example":"Long-term investors sometimes respond to rare market- wide dislocations."},{"kind":"phrase","front":"be indifferent to valuations","meaning":"对估值不在意","example":"Long-term investing doesn’t mean being indifferent to valuations."},{"kind":"phrase","front":"market timing / time the market","meaning":"择时／精准踩点入市","example":"Valuation-based decisions aren’t necessarily the same as trying to time every move."},{"kind":"phrase","front":"trim a position","meaning":"减持部分仓位","example":"An investor might trim a position when valuations become stretched."},{"kind":"phrase","front":"add aggressively","meaning":"较大力度地加仓","example":"Some investors add aggressively during major sell-offs."},{"kind":"phrase","front":"valuations look stretched","meaning":"估值偏高、被拉得过满","example":"I’d be cautious if valuations looked stretched."},{"kind":"phrase","front":"fair value / intrinsic value","meaning":"合理价值／内在价值","example":"Price and intrinsic value can diverge."},{"kind":"phrase","front":"calling the bottom","meaning":"判断最低点","example":"Recognizing an attractive valuation isn’t the same as calling the bottom."},{"kind":"phrase","front":"a good entry point","meaning":"合适的买入切入点","example":"A sharp decline may create a good entry point, but not automatically."},{"kind":"phrase","front":"have a track record","meaning":"有历史业绩记录、过往表现","example":"I follow investors who have a solid track record."},{"kind":"phrase","front":"cautiously optimistic","meaning":"谨慎乐观","example":"I’m cautiously optimistic, but I’m keeping some cash in reserve."},{"kind":"phrase","front":"either scenario could play out","meaning":"两种情境都有可能发生","example":"Both scenarios are plausible, and either could play out."},{"kind":"phrase","front":"adjust my assessment as new information comes in","meaning":"随着信息更新调整判断","example":"I adjust my assessment as new information comes in."},{"kind":"phrase","front":"temporary volatility / structural change","meaning":"短期波动／结构性变化","example":"I try to distinguish temporary volatility from structural change."},{"kind":"phrase","front":"retain control of Congress","meaning":"保持对国会的控制","example":"The market could react differently depending on which party retains control of Congress."},{"kind":"phrase","front":"political uncertainty weighs on sentiment","meaning":"政治不确定性压制市场情绪","example":"Political uncertainty may be weighing on investor sentiment."},{"kind":"phrase","front":"drag out a conflict","meaning":"拖延冲突","example":"One theory is that both sides have incentives to drag out the conflict."},{"kind":"phrase","front":"lose leverage / gain leverage","meaning":"失去／获得谈判筹码","example":"The theory assumes one side could lose leverage after the election."},{"kind":"phrase","front":"put political pressure on","meaning":"对……施加政治压力","example":"Higher energy prices could put political pressure on policymakers."},{"kind":"phrase","front":"take the gloves off","meaning":"不再留手、采取更强硬手段（口语比喻）","example":"Some commentators worry the administration might take the gloves off after the vote."},{"kind":"phrase","front":"exercise restraint / abandon restraint","meaning":"保持克制／不再克制","example":"An escalation scenario assumes the parties abandon restraint."},{"kind":"phrase","front":"destabilize / topple a government","meaning":"使政权不稳定／推翻政权（不同强度）","example":"A strike might destabilize a government; “topple” would mean actually bringing it down."},{"kind":"phrase","front":"pave the way for","meaning":"为……铺平道路","example":"An easing of tensions might pave the way for a market recovery."},{"kind":"phrase","front":"spill over into","meaning":"外溢、传导至","example":"A U.S. rally could spill over into Chinese equities."},{"kind":"phrase","front":"global risk appetite","meaning":"全球风险偏好","example":"Falling yields can sometimes improve global risk appetite."},{"kind":"phrase","front":"the 10-year Treasury yield","meaning":"美国 10 年期国债收益率","example":"A decline in the 10-year Treasury yield might support equity valuations."},{"kind":"phrase","front":"funds flow back into equities","meaning":"资金重新流入股票市场","example":"Some investors expect funds to flow back into equities."},{"kind":"phrase","front":"a plausible scenario","meaning":"合理但未证实的情境","example":"I see this as a plausible scenario, not a firm prediction."},{"kind":"phrase","front":"a speculative theory","meaning":"推测性的观点、理论","example":"It’s a speculative theory I came across online."},{"kind":"phrase","front":"play out","meaning":"（情境、局势）最终演变或发生","example":"We don’t know how the situation will play out."},{"kind":"phrase","front":"fall further than expected","meaning":"跌幅超出预期","example":"Prices can fall further than even experienced investors expect."},{"kind":"phrase","front":"short-term horizon / long-term horizon","meaning":"短期／长期观察与投资期限","example":"Markets sometimes focus on a much shorter horizon during a crisis."},{"kind":"phrase","front":"heightened uncertainty","meaning":"加剧的不确定性","example":"Heightened uncertainty makes long-term predictions harder."},{"kind":"phrase","front":"revise our assumptions","meaning":"修正原有假设","example":"We have to revise our assumptions when the facts change."},{"kind":"phrase","front":"a range of possible outcomes","meaning":"一系列可能结果","example":"I prefer thinking in terms of a range of possible outcomes."},{"kind":"phrase","front":"policy support / liquidity support","meaning":"政策支持／流动性支持","example":"Liquidity support could improve sentiment without guaranteeing a rally."},{"kind":"phrase","front":"underlying earnings power","meaning":"企业底层、可持续的盈利能力","example":"What matters most to me is a company’s underlying earnings power."},{"kind":"phrase","front":"the ability to generate profits","meaning":"创造利润的能力","example":"I’d worry if its ability to generate profits was permanently damaged."},{"kind":"phrase","front":"earnings capacity","meaning":"盈利能力、利润创造能力","example":"A temporary setback doesn’t necessarily weaken long- term earnings capacity."},{"kind":"phrase","front":"structural deterioration","meaning":"结构性恶化","example":"Structural deterioration worries me more than a temporary slowdown."},{"kind":"phrase","front":"temporary headwinds","meaning":"短期不利因素","example":"Higher energy costs may create temporary headwinds."},{"kind":"phrase","front":"permanent impairment","meaning":"永久性损伤（价值、盈利能力等）","example":"A permanent impairment of earning power is a more serious concern."},{"kind":"phrase","front":"cyclical slowdown","meaning":"周期性放缓","example":"A cyclical slowdown can hurt profits without permanently destroying the business."},{"kind":"phrase","front":"profit margins get squeezed","meaning":"利润率受到挤压","example":"When input costs rise, manufacturers’ profit margins can get squeezed."},{"kind":"phrase","front":"pass costs on to customers","meaning":"把成本转嫁给消费者","example":"Some companies can pass higher costs on to customers."},{"kind":"phrase","front":"market share erosion / lose market share","meaning":"市场份额遭侵蚀／失去份额","example":"Losing market share for years could point to deeper problems."},{"kind":"phrase","front":"recover once pressure eases","meaning":"压力缓解后恢复","example":"Profits might recover once energy prices ease."},{"kind":"phrase","front":"industry-wide / economy-wide","meaning":"全行业的／整个经济层面的","example":"An industry-wide shock isn’t necessarily unique to a single company."},{"kind":"phrase","front":"macro-driven vs company-specific","meaning":"宏观因素驱动／公司自身因素","example":"I want to distinguish macro-driven weakness from company-specific damage."},{"kind":"phrase","front":"diversification / index exposure","meaning":"分散化／指数敞口","example":"Index exposure spreads company-specific risk across many holdings."},{"kind":"phrase","front":"profitability has been impaired","meaning":"盈利能力已经受损","example":"I would slow my buying if long-term profitability had been impaired."},{"kind":"sentence","front":"It was more of a token purchase than a meaningful addition to my position.","meaning":"","example":""},{"kind":"sentence","front":"I can only add to my position gradually, in small increments.","meaning":"","example":""},{"kind":"sentence","front":"Which stocks would rebound faster than others?","meaning":"","example":""},{"kind":"sentence","front":"At least capture broad-market returns.","meaning":"","example":""},{"kind":"sentence","front":"Potential catalysts that could trigger a rebound.","meaning":"","example":""},{"kind":"sentence","front":"It fell roughly 20% from its peak.","meaning":"","example":""},{"kind":"sentence","front":"I have a fair amount of confidence in their judgment.","meaning":"","example":""},{"kind":"sentence","front":"I hope the sell-off doesn’t turn into a full-blown crash.","meaning":"","example":""},{"kind":"sentence","front":"People assume long-term investors don’t care about timing.","meaning":"","example":""},{"kind":"sentence","front":"When the market surges far beyond fair value.","meaning":"","example":""},{"kind":"sentence","front":"Even some of the most bearish investors.","meaning":"","example":""},{"kind":"sentence","front":"This drawdown is extreme by historical standards.","meaning":"","example":""},{"kind":"sentence","front":"Some of the political uncertainty could ease after the election.","meaning":"","example":""},{"kind":"sentence","front":"Money could flow back into equities.","meaning":"","example":""},{"kind":"sentence","front":"Take the gloves off / abandon restraint.","meaning":"","example":""},{"kind":"sentence","front":"The conflict could escalate again.","meaning":"","example":""},{"kind":"sentence","front":"Some investors have already factored in that possibility.","meaning":"","example":""},{"kind":"sentence","front":"Markets tend to price in near-term risks and adjust as circumstances change.","meaning":"","example":""},{"kind":"sentence","front":"A company’s underlying ability to generate profits.","meaning":"","example":""},{"kind":"sentence","front":"Other factors may affect the timing of the recovery rather than long-term earnings power.","meaning":"","example":""},{"kind":"sentence","front":"Their costs could fall as oil prices ease.","meaning":"","example":""},{"kind":"sentence","front":"It may be a company-specific problem or a broader macroeconomic issue.","meaning":"","example":""},{"kind":"sentence","front":"Many shocks affect the pace of the broader economy’s recovery.","meaning":"","example":""},{"kind":"phrase","front":"Compared with / relative to ...","meaning":"与……相比，强调相对规模。","example":"Compared with my existing holdings, this was a tiny purchase."},{"kind":"phrase","front":"... might ... without necessarily ...","meaning":"避免过度推论。","example":"A temporary shock might hurt profits without necessarily impairing the business long term."},{"kind":"paragraph","front":"I’ve mainly been buying broad-market index funds. Given how widespread the sell-off has been, I find it difficult to predict which individual stocks will rebound fastest. Rather than trying to pick the winners, I’d prefer to capture the performance of a broad benchmark. My latest purchase was tiny compared with my existing holdings—more of a token buy than a meaningful addition. I don’t have much spare cash, so I’m building my position in small increments. If valuations become even more attractive, I may step up my purchases.","meaning":"","example":""},{"kind":"paragraph","front":"When I mention a 20% or 30% decline, I’m not using that number as proof that the market is cheap. I’m simply trying to illustrate the severity of the sell-off. I also look at other indicators, especially valuations and historical extremes. Even some bearish observers think certain parts of the market are no longer especially expensive. But that still doesn’t guarantee an immediate rebound. What worries me is that I can’t identify a convincing catalyst that would turn investor sentiment around and support a sustained recovery.","meaning":"","example":""},{"kind":"paragraph","front":"I think it’s misleading to assume that long-term investors don’t care about timing at all. There’s a difference between trying to predict every short-term market move and making occasional decisions based on valuation. If a broad market is under severe pressure and prices become attractive, a long-term investor may add to their holdings. On the other hand, if valuations become stretched, they may trim some positions. That doesn’t mean they can call the exact bottom or top. It simply means that long-term investing and valuation awareness can go hand in hand.","meaning":"","example":""},{"kind":"paragraph","front":"I’ve come across two competing theories about what might happen after the U.S. midterm elections. One is that political uncertainty could ease, geopolitical tensions might cool down, and investor confidence could improve. That could pave the way for a rebound in U.S. equities, with some of the improvement in sentiment spilling over into Chinese stocks. The other theory is almost the opposite: once the vote is over, policymakers might feel less restrained, tensions could escalate, and markets might fall before recovering. I’m not presenting either theory as a fact. Both scenarios have some logic, but it’s difficult to know how much of the risk is already priced in.","meaning":"","example":""},{"kind":"paragraph","front":"Some investors may have already factored a possible escalation into their expectations, but that doesn’t mean the risk is fully priced in across the market. A sudden development could still catch investors off guard. In a highly uncertain environment, long-range forecasts become less reliable, and markets often focus on near-term risks. Rather than assuming I can predict what will happen years from now, I prefer to think through several possible outcomes and revise my assessment as new information comes in.","meaning":"","example":""},{"kind":"paragraph","front":"What would really make me reconsider my buying plan is evidence of a lasting deterioration in companies’ underlying earnings power. Higher oil prices or a geopolitical shock may squeeze profit margins temporarily. If those pressures fade, some companies could recover. But losing market share for years, facing a permanent competitive disadvantage, or seeing demand structurally weaken would be much more serious. Since I’m buying index funds, I try to distinguish economy-wide shocks from structural damage to the long-term profitability of a broad range of businesses.","meaning":"","example":""},{"kind":"phrase","front":"Squat down","meaning":"蹲下","example":"Squat down to lift the box without straining your back."},{"kind":"phrase","front":"Bend over","meaning":"弯腰","example":"He bent over to pick up his backpack."},{"kind":"phrase","front":"Slump","meaning":"瘫坐、无力地垂下身体","example":"After the long hike, I slumped into a chair."},{"kind":"phrase","front":"Curl up","meaning":"蜷缩身体","example":"She curled up on the sofa under a blanket."},{"kind":"phrase","front":"Roll over","meaning":"翻身","example":"I rolled over and switched off the alarm."},{"kind":"phrase","front":"Push yourself up","meaning":"撑起身体","example":"He pushed himself up from the ground."},{"kind":"phrase","front":"Jog","meaning":"慢跑","example":"I usually jog around the park in the morning."},{"kind":"phrase","front":"Sprint","meaning":"冲刺、全速奔跑","example":"He sprinted to catch the train."},{"kind":"phrase","front":"Dash","meaning":"猛冲、飞奔","example":"She dashed outside when she heard the doorbell."},{"kind":"phrase","front":"Dodge","meaning":"躲闪、闪避","example":"I dodged a low branch as I ran down the trail."},{"kind":"phrase","front":"Stumble","meaning":"绊一下、踉跄","example":"I stumbled over a loose rock but didn't fall."},{"kind":"phrase","front":"Stagger","meaning":"摇摇晃晃地走","example":"He staggered back to the campsite, exhausted."},{"kind":"phrase","front":"Limp","meaning":"一瘸一拐地走","example":"She limped back after twisting her ankle."},{"kind":"phrase","front":"Trudge","meaning":"拖着沉重的步伐行走","example":"We trudged through the snow for another hour."},{"kind":"phrase","front":"Sidestep","meaning":"侧身避开","example":"I sidestepped a puddle on the trail."},{"kind":"phrase","front":"Scramble up","meaning":"手脚并用地爬上去","example":"We scrambled up the final rocky slope."},{"kind":"phrase","front":"Clamber over","meaning":"费力地攀爬、翻越","example":"He clambered over a fallen tree."},{"kind":"phrase","front":"Wade through","meaning":"涉水穿过","example":"We had to wade through knee-deep water."},{"kind":"phrase","front":"Traverse","meaning":"横切、横越","example":"We traversed a steep hillside to reach the pass."},{"kind":"phrase","front":"Grip","meaning":"紧紧握住","example":"Grip the handrail firmly on the way down."},{"kind":"phrase","front":"Grab hold of","meaning":"迅速抓牢","example":"I grabbed hold of a branch to keep my balance."},{"kind":"phrase","front":"Haul yourself up","meaning":"用力把自己拉上去","example":"She hauled herself up onto the ledge."},{"kind":"phrase","front":"Retrace your steps","meaning":"原路返回","example":"We retraced our steps when the path disappeared."},{"kind":"phrase","front":"Lean back","meaning":"身体后仰、向后靠","example":"Lean back against the wall and relax."},{"kind":"phrase","front":"Straighten up","meaning":"挺直身体、直起腰","example":"He straightened up after tying his boots."},{"kind":"phrase","front":"Sit cross-legged","meaning":"盘腿坐","example":"We sat cross-legged on the grass."},{"kind":"phrase","front":"Lie flat on your back","meaning":"仰面平躺","example":"Lie flat on your back and look up at the sky."},{"kind":"phrase","front":"Roll onto your side","meaning":"翻身侧躺","example":"She rolled onto her side to get comfortable."},{"kind":"phrase","front":"Stretch out","meaning":"伸展开身体、舒展四肢","example":"Stretch out your arms and legs after the flight."},{"kind":"phrase","front":"Bend down","meaning":"弯下腰、俯身","example":"He bent down to pick up his keys."},{"kind":"phrase","front":"Tiptoe","meaning":"踮着脚尖轻轻走","example":"She tiptoed past the sleeping baby."},{"kind":"phrase","front":"Shuffle along","meaning":"拖着脚、迈着小碎步走","example":"The tired hikers shuffled along the path."},{"kind":"phrase","front":"Stroll","meaning":"悠闲地散步","example":"We strolled along the river after dinner."},{"kind":"phrase","front":"Stride","meaning":"大步走","example":"He strode across the room to greet us."},{"kind":"phrase","front":"Sneak past","meaning":"悄悄地从旁边经过","example":"I sneaked past the sleeping dog."},{"kind":"phrase","front":"Lunge forward","meaning":"猛地向前扑、向前跨出弓步","example":"She lunged forward to catch the ball."},{"kind":"phrase","front":"Leap over","meaning":"跃过、跳过","example":"He leapt over a narrow stream."},{"kind":"phrase","front":"Duck under","meaning":"低头钻过、弯身避开","example":"We ducked under a low branch."},{"kind":"phrase","front":"Slip","meaning":"脚下打滑","example":"I slipped on the wet pavement."},{"kind":"phrase","front":"Reach for","meaning":"伸手去拿、去够","example":"She reached for her phone on the shelf."},{"kind":"phrase","front":"Clutch","meaning":"紧紧抓住、攥住","example":"He clutched his bag as the bus lurched forward."},{"kind":"phrase","front":"Tug at","meaning":"拉扯、拽动","example":"The child tugged at my sleeve."},{"kind":"phrase","front":"Yank","meaning":"猛拉、猛拽","example":"She yanked the door open."},{"kind":"phrase","front":"Shove","meaning":"用力推、推搡","example":"He shoved the heavy box across the floor."},{"kind":"phrase","front":"Hoist","meaning":"用力举起、吊起重物","example":"They hoisted the supplies onto the roof."},{"kind":"phrase","front":"Flick","meaning":"用手指轻弹、快速甩动","example":"He flicked a bit of dust off his sleeve."},{"kind":"phrase","front":"Rub","meaning":"揉搓、摩擦","example":"Rub your hands together to warm them up."},{"kind":"phrase","front":"Shrug","meaning":"耸肩","example":"She shrugged when I asked what happened."},{"kind":"phrase","front":"Glance at","meaning":"快速瞥一眼","example":"He glanced at his watch and hurried out."},{"kind":"phrase","front":"Crane your neck","meaning":"伸长脖子张望","example":"We craned our necks to see over the crowd."},{"kind":"phrase","front":"Tap","meaning":"轻敲；例如手指轻敲桌面","example":"She tapped her fingers lightly on the desk."},{"kind":"phrase","front":"Bang","meaning":"砰砰地敲、猛击；例如用力敲门或墙","example":"Someone is banging on the wall."},{"kind":"phrase","front":"Pound","meaning":"连续用力敲打；例如不断猛敲墙壁","example":"Someone kept pounding on the wall late at night."},{"kind":"phrase","front":"Hammer","meaning":"锤击、反复敲打；例如用锤子敲东西","example":"It sounds like someone is hammering something."},{"kind":"phrase","front":"Thump","meaning":"沉重地敲击；发出低沉的咚声","example":"A heavy box landed with a thump."},{"kind":"phrase","front":"Rattle","meaning":"哐啷作响；物体连续振动碰撞","example":"The loose window frame rattled in the wind."},{"kind":"phrase","front":"A muffled sound","meaning":"沉闷、模糊的声音；被墙壁或门阻隔","example":"The noise is muffled, but I can still hear it clearly."},{"kind":"phrase","front":"A dull thud","meaning":"沉闷的咚声；重物撞击发出的低沉声音","example":"I keep hearing a dull thud through the wall."},{"kind":"phrase","front":"A deep sound","meaning":"低沉的声音；强调音调低","example":"The drum made a deep sound that carried down the hall."},{"kind":"phrase","front":"A low rumble","meaning":"低沉的隆隆声；如雷声、机器声或远处震动","example":"There's a low, rumbling noise coming from the next room."},{"kind":"phrase","front":"A hollow sound","meaning":"空洞的声音；敲击空心物体产生的声音","example":"The empty container made a hollow sound when I tapped it."},{"kind":"phrase","front":"A muted sound","meaning":"低弱、受到抑制的声音；不响亮、不清脆","example":"The footsteps made a muted sound on the thick carpet."},{"kind":"phrase","front":"Bang on the wall","meaning":"用力敲墙","example":"I heard someone bang on the wall twice."},{"kind":"phrase","front":"A muffled noise","meaning":"隔着障碍物传来的闷响","example":"We could hear a muffled noise through the closed door."},{"kind":"phrase","front":"A constant thumping noise","meaning":"持续不断的沉闷咚咚声","example":"There's a constant thumping noise coming from upstairs."},{"kind":"phrase","front":"Initiate physical contact","meaning":"主动发起身体接触","example":"The defender initiated physical contact as the winger cut inside."},{"kind":"phrase","front":"Engage in physical duels","meaning":"参与身体对抗","example":"The midfielder isn't afraid to engage in physical duels."},{"kind":"phrase","front":"extreme situations call for calm","meaning":"极端情况下尤其需要保持冷静","example":"Extreme situations call for calm, not panic."},{"kind":"phrase","front":"go viral on social media","meaning":"在社交媒体上爆火","example":"A post about everyday spending went viral."},{"kind":"phrase","front":"seem insignificant","meaning":"看起来微不足道","example":"Each purchase seems insignificant on its own."},{"kind":"phrase","front":"individually / taken together","meaning":"单独来看／合在一起看","example":"Individually they seem cheap; taken together, they cost a lot."},{"kind":"phrase","front":"before you know it","meaning":"不知不觉间","example":"Before you know it, you have spent hundreds."},{"kind":"phrase","front":"eat into your savings","meaning":"逐渐侵蚀储蓄","example":"Frequent small purchases can eat into your savings."},{"kind":"phrase","front":"warm and welcoming","meaning":"热情友好、令人宾至如归","example":"The staff were warm and welcoming."},{"kind":"phrase","front":"outgoing and expressive","meaning":"外向、善于表达","example":"The receptionist was outgoing and expressive."},{"kind":"phrase","front":"reserved","meaning":"内敛、话少，但不一定不友善","example":"The staff were polite but fairly reserved."},{"kind":"phrase","front":"greet someone with a smile","meaning":"微笑迎接某人","example":"I appreciate being greeted with a smile."},{"kind":"phrase","front":"the essentials","meaning":"必须知道的基本信息","example":"Just give me the essentials, like check-out time and Wi-Fi."},{"kind":"phrase","front":"dwell on something","meaning":"反复纠结某件事","example":"I would not dwell on it, but I might not recommend the hostel."},{"kind":"phrase","front":"leave it at that","meaning":"就此打住、不再多说","example":"I collect my key card and leave it at that."},{"kind":"phrase","front":"keep to oneself","meaning":"独处、不太主动社交","example":"At the campsite, most guests kept to themselves."},{"kind":"phrase","front":"communal areas / common room","meaning":"公共区域／公共休息室","example":"People chatted in the common room."},{"kind":"phrase","front":"team up","meaning":"结伴做某事","example":"A few guests teamed up to explore the city."},{"kind":"phrase","front":"stick to my own itinerary","meaning":"按自己的行程走","example":"I usually prefer to stick to my own itinerary."},{"kind":"phrase","front":"comfortable with my own company","meaning":"享受独处、自得其乐","example":"I am comfortable with my own company."},{"kind":"phrase","front":"enjoy solitude","meaning":"享受独处","example":"Being alone does not feel sad to me; I enjoy solitude."},{"kind":"phrase","front":"touristy area / residential neighborhood","meaning":"游客集中的区域／居民社区","example":"I spent most of my time in touristy areas, not residential neighborhoods."},{"kind":"phrase","front":"push up rents","meaning":"推高租金","example":"Some residents argue that tourist accommodation pushes up rents."},{"kind":"phrase","front":"housing shortage / housing supply","meaning":"住房短缺／住房供给","example":"We should address the housing shortage by increasing supply."},{"kind":"phrase","front":"bring money into the local economy","meaning":"为当地经济带来收入","example":"Tourists bring money into the local economy."},{"kind":"sentence","front":"In Northern Europe, people seem more reserved.","meaning":"","example":""},{"kind":"sentence","front":"That reminds me of a time in Poland.","meaning":"","example":""},{"kind":"sentence","front":"I wouldn’t dwell on it.","meaning":"","example":""},{"kind":"sentence","front":"A professional relationship between a guest and hotel staff.","meaning":"","example":""},{"kind":"sentence","front":"They could team up to explore the city.","meaning":"","example":""},{"kind":"sentence","front":"I enjoy solitude. / I enjoy being alone.","meaning":"","example":""},{"kind":"sentence","front":"I don’t always feel like socializing.","meaning":"","example":""},{"kind":"sentence","front":"I didn’t visit many residential neighborhoods.","meaning":"","example":""},{"kind":"sentence","front":"Perhaps the city should build more housing.","meaning":"","example":""},{"kind":"phrase","front":"In my experience, A tend to ..., whereas B ...","meaning":"对比两个观察到的倾向，不应概括全部人。","example":"In my experience, receptionists in Southern Europe tend to be more expressive, whereas some in Northern Europe are more reserved."},{"kind":"phrase","front":"I’m comfortable with either ..., as long as ...","meaning":"表示接受两种选择，但有前提。","example":"I’m comfortable with either style, as long as the staff are respectful and kind."},{"kind":"phrase","front":"I wouldn’t dwell on ..., but ...","meaning":"表达不纠结，但承认影响。","example":"I wouldn’t dwell on a cold welcome, but it might affect my review."},{"kind":"phrase","front":"The issue isn’t just ...; it’s also ...","meaning":"避免单一归因。","example":"The issue isn’t just the number of visitors; it’s also the supply of housing."},{"kind":"phrase","front":"We should focus on ... rather than ...","meaning":"政策/个人建议中的对照句式。","example":"We should focus on increasing housing supply rather than blaming individual tourists."},{"kind":"phrase","front":"Small ... can add up to ... before you know it.","meaning":"日常小额消费积累效应。","example":"Small everyday purchases can add up to hundreds before you know it."},{"kind":"paragraph","front":"I recently came across a post that went viral on Chinese social media. It showed how small everyday expenses can add up. A purchase for 9.90 or 19.90 might seem insignificant on its own, but when you add up all those little purchases, the total can be surprisingly high. Before you know it, you've spent hundreds without really noticing. I think that's why small expenses are so easy to overlook: none of them feels like a big decision at the time.","meaning":"","example":""},{"kind":"paragraph","front":"In my experience, receptionists in Italy and Greece tend to be warmer and more expressive, while those I've met in Northern Europe have sometimes been more reserved. I don't necessarily prefer one style over the other. I'm comfortable with either approach as long as the staff are polite, respectful, and helpful. A simple smile and a clear explanation of the essentials are enough for me. I don't expect a personal connection; I just want to feel welcome and know what I need to know.","meaning":"","example":""},{"kind":"paragraph","front":"I remember staying at a hostel in Poland where the receptionist had a poker face. It left me with a slightly negative impression, although I wouldn't dwell on it. I would still collect my key card, listen to the essential information, and leave it at that. If the service was cold, I might mention it in a review or be less likely to recommend the hostel. But I wouldn't let one awkward interaction ruin the whole trip.","meaning":"","example":""},{"kind":"paragraph","front":"I'm an introvert, but that doesn't mean I can't socialize. I can strike up a conversation when I need to; I just don't always feel like doing it. At a campsite in Iceland, most people seemed to keep to themselves. In hostels in Rome and Naples, I saw guests chatting in communal areas and sometimes teaming up to explore the city. I enjoyed watching people socialize, but I was equally happy sticking to my own itinerary. I'm comfortable with my own company, and being alone doesn't feel lonely to me.","meaning":"","example":""},{"kind":"paragraph","front":"I've seen slogans in Barcelona telling tourists to go home, and I find that attitude unfair toward individual visitors. Tourism brings money into the local economy and creates opportunities for some businesses and workers, even though the benefits aren't evenly distributed. I understand that residents may be frustrated by rising rents and pressure on their neighborhoods. Still, I don't think blaming individual tourists solves the underlying problem. From my perspective, cities should focus on long-term solutions, such as increasing housing supply and examining how short-term rentals affect residential housing.","meaning":"","example":""},{"kind":"phrase","front":"downplay","meaning":"动词｜淡化；轻描淡写；低估重要性或风险","example":"常见搭配：downplay a risk / a problem / the significance of sth.\n① The report downplays the risks of relying on property sales.\n② Don’t downplay how difficult this exam will be."},{"kind":"phrase","front":"fiscal firepower","meaning":"名词搭配｜财政政策的资金实力、政策空间","example":"常见搭配：give a government fiscal firepower; have / lack fiscal firepower\n① Higher tax revenue gave the government more fiscal firepower to support infrastructure.\n② A large budget deficit may limit fiscal firepower during a recession."},{"kind":"phrase","front":"dire problems","meaning":"形容词搭配｜严重的问题；迫切需要解决的问题","example":"常见搭配：a dire problem / situation / shortage; dire consequences\n① A housing shortage has created dire problems for young families.\n② If we ignore these warnings, we could face dire problems later."},{"kind":"phrase","front":"implosion","meaning":"名词｜内部崩溃；迅速瓦解（也可指物理“内爆”）","example":"常见搭配：the implosion of a market / company / political party\n① The property market’s implosion left local banks under pressure.\n② The team’s sudden implosion surprised everyone."},{"kind":"phrase","front":"mop up","meaning":"短语动词｜扫光；吃下/拿走大部分；清理剩余部分","example":"常见搭配：mop up cheap assets / available shares / the remaining supply\n① Large funds mopped up the cheap assets after the sell-off.\n② He used a piece of bread to mop up the last of the sauce."},{"kind":"phrase","front":"latecomers","meaning":"名词复数｜后来者；迟到者；后入场的人","example":"常见搭配：latecomers to a market / trend / course\n① Latecomers to the rally often bought near the peak.\n② The teacher gave latecomers a quick summary of the lesson."},{"kind":"phrase","front":"lingering recessions","meaning":"名词搭配｜迟迟未结束的经济衰退","example":"常见搭配：a lingering recession; lingering doubts / pain / effects\n① High debt can turn a slowdown into a lingering recession.\n② The region is still suffering from a lingering recession."},{"kind":"phrase","front":"slump in … / plunge … into …","meaning":"整句结构｜……下滑；使……突然陷入……","example":"常见搭配：a slump in + 市场/行业；plunge + 人/地区 + into + 危机/黑暗\n① A slump in exports plunged the town into a deep recession.\n② The sudden power failure plunged the building into darkness."},{"kind":"phrase","front":"financial convulsion","meaning":"名词搭配｜剧烈金融震荡；金融体系动荡","example":"常见搭配：a financial convulsion; economic / political convulsions\n① The banking collapse triggered a financial convulsion across the country.\n② The country avoided a financial convulsion, but growth remained weak."},{"kind":"phrase","front":"the fuel of wars","meaning":"名词搭配｜战争的燃料；引发或推动战争的因素","example":"常见搭配：be the fuel of wars; fuel for conflict; fuel tensions（动词）\n① Competition for scarce resources has often been the fuel of wars.\n② False rumors can provide fuel for conflict between communities."},{"kind":"phrase","front":"national anthems","meaning":"名词复数｜国歌","example":"常见搭配：sing / play a national anthem; the lyrics of an anthem\n① The two national anthems were played before the match.\n② She knows every word of her country’s national anthem."},{"kind":"phrase","front":"agitate over","meaning":"动词短语｜围绕某事激烈争论、鼓动","example":"常见搭配：agitate over an issue; agitate for reform; agitate against a policy\n① Residents agitated over the proposed changes to land ownership.\n② Students began to agitate for better public transport."},{"kind":"phrase","front":"during the twilight of the nineteenth century","meaning":"时间表达｜在19世纪末期；在一个时代的暮年","example":"常见搭配：during the twilight of an era / empire / career\n① During the twilight of the empire, political instability increased.\n② During the twilight of his career, he became a mentor to younger players."},{"kind":"phrase","front":"mount","meaning":"动词｜发起、组织（运动/挑战/行动）；原文为 mounted，并非只有“登山”义","example":"常见搭配：mount a campaign / challenge / protest / legal action\n① Citizens mounted a campaign against the new tax.\n② The company mounted a legal challenge to the decision."},{"kind":"phrase","front":"grinding poverty","meaning":"名词搭配｜极端贫困；长期而沉重的贫困","example":"常见搭配：live in / be trapped in grinding poverty\n① Many families remained trapped in grinding poverty.\n② A new factory brought jobs to an area marked by grinding poverty."},{"kind":"phrase","front":"seized and appropriated","meaning":"动词被动结构｜被夺取并占用/征用","example":"常见搭配：seize property; appropriate assets / land / funds\n① During the war, several buildings were seized and appropriated by the army.\n② The authorities seized the site and appropriated it for public use."},{"kind":"phrase","front":"the linchpin of the global financial system","meaning":"名词搭配｜全球金融体系的关键支柱/核心环节","example":"常见搭配：the linchpin of a system / strategy / team\n① Trust is the linchpin of the banking system.\n② Reliable transport is a linchpin of the regional economy."},{"kind":"phrase","front":"reap huge rewards","meaning":"动词搭配｜获得丰厚回报；收获巨大成果","example":"常见搭配：reap rewards / benefits / profits; reap the rewards of sth.\n① Early investors reaped huge rewards from the company’s growth.\n② With steady practice, you can reap the rewards of your hard work."},{"kind":"phrase","front":"a thriving area","meaning":"名词搭配｜繁荣发展的地区；兴旺的区域","example":"常见搭配：a thriving city / neighborhood / community / business\n① The former industrial district has become a thriving area.\n② Small cafés often do well in a thriving neighborhood."},{"kind":"phrase","front":"irreconcilable goals","meaning":"名词搭配｜不可调和的目标；彼此冲突的目标","example":"常见搭配：irreconcilable goals / differences / interests\n① The policy tries to balance two seemingly irreconcilable goals.\n② They had irreconcilable goals and decided to work separately."},{"kind":"phrase","front":"pernicious","meaning":"形容词｜有严重危害的；有害且常不易察觉的","example":"常见搭配：a pernicious effect / influence / cycle / myth\n① A pernicious cycle of debt and rising interest costs emerged.\n② The rumor had a pernicious effect on trust within the team."},{"kind":"phrase","front":"prospect","meaning":"名词｜前景；可能性；预期发生的事","example":"常见搭配：the prospect of + 名词/doing；prospects for growth\n① The prospect of higher interest rates worried borrowers.\n② She was excited by the prospect of studying abroad."},{"kind":"phrase","front":"perilously","meaning":"副词｜危险地；接近危险程度地","example":"常见搭配：perilously close to; perilously high / low\n① Household debt is perilously high in some economies.\n② The hikers were perilously close to the cliff edge."},{"kind":"phrase","front":"snared in","meaning":"动词短语｜被困在……中；陷入难以摆脱的处境","example":"常见搭配：be / become / find oneself snared in a trap / cycle / dispute\n① The country became snared in a cycle of debt and weak growth.\n② The bird was snared in a net and could not escape."},{"kind":"phrase","front":"stick to a routine","meaning":"保持固定的生活规律","example":"I like to stick to a routine, but I leave room for flexibility."},{"kind":"phrase","front":"follow more or less the same routine","meaning":"每天大致按照相同规律生活","example":"Most of my days follow more or less the same routine."},{"kind":"phrase","front":"leave room for flexibility","meaning":"保留灵活调整的空间","example":"I make plans in advance but leave room for flexibility."},{"kind":"phrase","front":"the predictability of a routine","meaning":"规律的可预期性","example":"It's the predictability of my routine that makes me comfortable."},{"kind":"phrase","front":"put me at ease","meaning":"让我安心、放松","example":"Having a familiar routine puts me at ease."},{"kind":"phrase","front":"set the tone for the day","meaning":"为一整天定下基调","example":"A calm morning helps set the tone for the day."},{"kind":"phrase","front":"a quick bite","meaning":"简单快速吃点东西","example":"I usually just grab a quick bite for breakfast."},{"kind":"phrase","front":"do the job","meaning":"够用、能满足基本需要","example":"Cornflakes and milk aren't exciting, but they do the job."},{"kind":"phrase","front":"put the kettle on / boil some water","meaning":"烧水（前者英式口语很常见）","example":"I'll make tea later when I have time to put the kettle on."},{"kind":"phrase","front":"brew a cup of tea","meaning":"泡一杯茶","example":"I prefer to brew tea when I'm not in a rush."},{"kind":"phrase","front":"run a promotion / have a deal on","meaning":"正在搞促销","example":"KFC is running a promotion today."},{"kind":"phrase","front":"great value for money","meaning":"性价比高","example":"If the meal really costs around nine euros, that's great value for money."},{"kind":"phrase","front":"too good a deal to pass up","meaning":"划算到不想错过","example":"It sounds almost too good a deal to pass up."},{"kind":"phrase","front":"crave something","meaning":"嘴馋、特别想吃某物","example":"I'm actually craving hot wings and fries."},{"kind":"phrase","front":"miss out on a deal","meaning":"错过优惠","example":"Part of me doesn't want to miss out on the deal."},{"kind":"phrase","front":"take several factors into account","meaning":"综合考虑多个因素","example":"I take taste, price, and convenience into account."},{"kind":"phrase","front":"spur-of-the-moment decision","meaning":"一时兴起做出的决定","example":"It's not a spur-of-the-moment decision; I knew about the deal last night."},{"kind":"phrase","front":"think something over","meaning":"仔细考虑某事","example":"I've had time to think it over."},{"kind":"phrase","front":"worthwhile / worth it","meaning":"值得（搭配不同）","example":"The meal might be worth it, but I still have other things to consider."},{"kind":"phrase","front":"attention versus accuracy","meaning":"吸引注意力与准确性之间的冲突","example":"Online content often rewards attention over accuracy."},{"kind":"phrase","front":"sensational headline","meaning":"耸人听闻的标题","example":"A sensational headline can attract more clicks than a careful report."},{"kind":"phrase","front":"cover up the truth","meaning":"掩盖真相（经常出现在煽动性标题中）","example":"The post claimed that officials were covering up the truth, without evidence."},{"kind":"phrase","front":"drive engagement","meaning":"带动互动、参与量","example":"Arguments in the comments can drive engagement."},{"kind":"phrase","front":"fuel controversy","meaning":"助长争议","example":"Even angry responses can fuel controversy."},{"kind":"phrase","front":"amplify a tendency","meaning":"放大一种倾向","example":"Algorithms can amplify tendencies that already exist in human nature."},{"kind":"phrase","front":"feed someone this kind of content","meaning":"不断给某人推送这类内容","example":"My feed keeps showing me this kind of content."},{"kind":"phrase","front":"cut down on scrolling","meaning":"减少刷手机的时间","example":"I've been trying to cut down on scrolling."},{"kind":"phrase","front":"curate my feed","meaning":"有意识地筛选信息流","example":"I try to curate my feed around things that make me laugh."},{"kind":"phrase","front":"leave me feeling anxious","meaning":"让我感到焦虑","example":"Some posts leave me feeling anxious for no good reason."},{"kind":"phrase","front":"cute pet videos / comedy clips","meaning":"可爱宠物视频／喜剧短视频","example":"These days, I mostly watch comedy clips and cute pet videos."},{"kind":"phrase","front":"run errands","meaning":"办杂事、跑腿","example":"If I go out, I prefer to run several errands."},{"kind":"phrase","front":"get everything done in one go","meaning":"一次性把事情办完","example":"I like to get everything done in one go."},{"kind":"phrase","front":"bundle errands together","meaning":"把多件外出事项安排在一起","example":"I usually bundle my errands together."},{"kind":"phrase","front":"feel physically tense","meaning":"身体感到紧绷","example":"I feel physically tense before going out for just one errand."},{"kind":"phrase","front":"feel resistant to doing something","meaning":"对做某事产生抗拒感","example":"I feel resistant to leaving the room, even when the task is simple."},{"kind":"phrase","front":"not a question of whether it's worth it","meaning":"不是值不值得的问题","example":"It's not a question of whether it's worth it; the discomfort feels physical."},{"kind":"phrase","front":"switch between different modes","meaning":"在不同状态之间切换","example":"I find it hard to switch between rest mode and activity mode."},{"kind":"phrase","front":"behavioural inertia","meaning":"行为惯性（解释假说，不是诊断）","example":"Maybe behavioural inertia plays a part, but I'm not sure."},{"kind":"phrase","front":"get into the right mindset","meaning":"进入合适的心理状态","example":"A full schedule seems to help me get into the right mindset."},{"kind":"phrase","front":"the hardest part is getting started","meaning":"最难的是开始行动","example":"For me, the hardest part is getting started."},{"kind":"phrase","front":"build momentum","meaning":"逐渐形成行动势头","example":"After the first task, I can build momentum."},{"kind":"phrase","front":"a clear plan gives the day structure","meaning":"明确的计划让一天更有结构","example":"Having a clear plan seems to make the transition easier."},{"kind":"phrase","front":"teleport somewhere","meaning":"瞬间移动到某处（虚构假设）","example":"If I could teleport anywhere for lunch, I'd go back to China."},{"kind":"phrase","front":"have no practical constraints","meaning":"不受现实条件限制","example":"If there were no practical constraints, I'd choose my hometown food."},{"kind":"phrase","front":"be shaped by what we grow up eating","meaning":"由从小吃的东西塑造口味","example":"Our tastes are shaped by what we grow up eating."},{"kind":"phrase","front":"develop a taste for","meaning":"逐渐喜欢上某种食物","example":"You can develop a taste for new dishes while still loving familiar food."},{"kind":"phrase","front":"the food I grew up with","meaning":"从小吃到大的食物","example":"I still crave the food I grew up with."},{"kind":"phrase","front":"a rich culinary tradition","meaning":"丰富的饮食文化传统","example":"My hometown has a rich culinary tradition built around wheat."},{"kind":"phrase","front":"texture and flavour","meaning":"口感与风味","example":"What I miss is the variety of textures and flavours."},{"kind":"phrase","front":"bring back memories","meaning":"勾起回忆","example":"Even thinking about those noodles brings back memories."},{"kind":"phrase","front":"be nostalgic for","meaning":"怀念、眷恋过去的某物","example":"I'm nostalgic for the food I ate growing up."},{"kind":"phrase","front":"have a soft spot for","meaning":"对某物有特别的偏爱","example":"I'll always have a soft spot for my hometown's food."},{"kind":"phrase","front":"feel familiar and comforting","meaning":"熟悉且令人安心","example":"Those flavours feel familiar and comforting."},{"kind":"sentence","front":"My days follow more or less the same routine.","meaning":"","example":""},{"kind":"sentence","front":"The familiar routine makes me feel at ease.","meaning":"","example":""},{"kind":"sentence","front":"Making tea takes a little time, especially when I have to boil water first.","meaning":"","example":""},{"kind":"sentence","front":"I'm torn between having eggs and milk and going to KFC.","meaning":"","example":""},{"kind":"sentence","front":"I've had time to think it over, so I'm mentally prepared.","meaning":"","example":""},{"kind":"sentence","front":"It's not a spur-of-the-moment decision.","meaning":"","example":""},{"kind":"sentence","front":"Algorithms amplify tendencies that are already part of human nature.","meaning":"","example":""},{"kind":"sentence","front":"I deliberately look for funny stories and comedy clips.","meaning":"","example":""},{"kind":"sentence","front":"Get a bunch of errands done in one go.","meaning":"","example":""},{"kind":"sentence","front":"I feel physically tense and resistant to going out.","meaning":"","example":""},{"kind":"sentence","front":"It's not about whether it's worth the effort. It's a physical reaction.","meaning":"","example":""},{"kind":"sentence","front":"Getting started takes a lot of effort for me.","meaning":"","example":""},{"kind":"sentence","front":"Our tastes are shaped by what we eat growing up.","meaning":"","example":""},{"kind":"sentence","front":"My hometown is famous for its wheat-based dishes.","meaning":"","example":""},{"kind":"sentence","front":"There are said to be over a hundred different ways to prepare wheat-based dishes.","meaning":"","example":""},{"kind":"phrase","front":"I wouldn't say A. It's more like B.","meaning":"不完全是 A，更接近 B","example":"I wouldn't say I'm excited about mornings. It's more that I like the routine."},{"kind":"phrase","front":"I've had time to think it over.","meaning":"我已经考虑了一阵子","example":"I knew about the promotion last night, so I've had time to think it over."},{"kind":"phrase","front":"What makes it difficult is...","meaning":"真正让它困难的是……","example":"What makes it difficult is the tension I feel before leaving."},{"kind":"phrase","front":"I'm still open to ..., but ...","meaning":"我仍愿意……，但……","example":"I'm still open to trying new dishes, but I miss familiar flavours from home."},{"kind":"paragraph","front":"My days are pretty repetitive, but I don't necessarily see that as a bad thing. I usually wake up around the same time, eat a simple breakfast, and get on with whatever I have planned. I prefer to plan ahead rather than deal with unexpected changes at the last minute, although I don't need every minute of my day scheduled. It's the predictability that puts me at ease. I'm not particularly excited about my routine, but I find it comfortable and reassuring. For breakfast, I usually grab a quick bite. I ran out of peanut butter today, so I had cornflakes and milk instead. Nothing special, but it does the job.","meaning":"","example":""},{"kind":"paragraph","front":"I'm torn between cooking at home and going to KFC. They're running a promotion, and if the advertised meal really comes to around nine euros, it sounds like great value for money. To be fair, it's not just the deal that attracts me. I'm also craving hot wings and fries, and not having to cook is a nice bonus. So it's a combination of taste, price, and convenience. I knew about the promotion last night, which means this isn't a spur-of-the-moment decision. I've had time to think it over. I haven't made up my mind yet, but I don't think the choice comes down to any single factor.","meaning":"","example":""},{"kind":"paragraph","front":"I don't think social media created our attraction to dramatic stories. People have always been curious about controversy, rumours, and shocking events. What has changed is the technology. Recommendation algorithms can identify what grabs our attention and keep feeding us similar content. Sometimes a misleading headline gets shared widely precisely because people argue about it, and that controversy drives even more engagement. In that sense, algorithms amplify tendencies that were already part of human nature. That's one reason I've been cutting down on scrolling. These days, I'd rather watch a funny clip or a cute pet video than spend an hour reading arguments that leave me feeling anxious.","meaning":"","example":""},{"kind":"paragraph","front":"There's something unusual about the way I organise my day. If I have nothing planned, I can stay in my room and spend hours in bed without feeling the need to go out. But if I have several errands to run, I can leave the house and get everything done in one go. The strange part is that going out for just one small errand can make me feel physically tense. It isn't simply that the task doesn't seem worth the effort. I actually feel resistant to making that transition. That's why the idea of switching between rest mode and activity mode makes sense to me. Once I get going, I can stay active for a long time. The hardest part is getting started.","meaning":"","example":""},{"kind":"paragraph","front":"If I could teleport anywhere in the world for lunch, I'd probably go straight back to China. Our tastes are shaped by what we grow up eating, and my hometown is especially famous for its wheat-based dishes. There are so many different ways to prepare them, with different shapes, textures, and flavours. I've tried a huge variety of those dishes, so there's a lot that I miss. I've been away for about a year, and I find myself missing that food more and more often. For me, it's not just about one bowl of noodles. It's about an entire culinary tradition that feels familiar and comforting.","meaning":"","example":""},{"kind":"paragraph","front":"I still enjoy trying new food whenever I travel. In fact, tasting local specialties is often one of the things I look forward to most on a trip. So missing my hometown food doesn't mean I've lost my curiosity about other cultures. The difference is that when I'm exploring somewhere new, I want to discover unfamiliar flavours. But if you ask me what I'd most like to eat right now, I'm likely to choose something I already know I love. That isn't a contradiction. I can be open to new experiences while still having a soft spot for the food I grew up with.","meaning":"","example":""},{"kind":"phrase","front":"sharp pain / stabbing pain","meaning":"锐痛／刺痛","example":"At first, it was a sharp pain that came back every few seconds."},{"kind":"phrase","front":"come and go / on and off","meaning":"时有时无／断断续续","example":"The pain comes and goes rather than staying constant."},{"kind":"phrase","front":"be sensitive to hot and cold","meaning":"对冷热敏感","example":"My tooth seems particularly sensitive to hot food and icy drinks."},{"kind":"phrase","front":"piping-hot / ice-cold","meaning":"滚烫的／冰凉的","example":"I had piping-hot chicken wings with an ice-cold drink."},{"kind":"phrase","front":"flare up","meaning":"症状突然加重、发作","example":"The pain flared up after that meal."},{"kind":"phrase","front":"ease off / subside","meaning":"逐渐减轻、缓解","example":"Fortunately, the pain has eased off since then."},{"kind":"phrase","front":"get worse / become more severe","meaning":"恶化、变得更严重","example":"If the pain gets worse, I will make a dental appointment."},{"kind":"phrase","front":"interfere with everyday life","meaning":"影响日常生活","example":"It is uncomfortable, but it is not interfering with my everyday life."},{"kind":"phrase","front":"chew / swallow normally","meaning":"正常咀嚼／吞咽","example":"I can still drink, chew and swallow normally."},{"kind":"phrase","front":"rinse my mouth / avoid cold water","meaning":"漱口／避免冷水","example":"I avoid rinsing my mouth with cold water because it triggers discomfort."},{"kind":"phrase","front":"battery drains quickly","meaning":"电池掉电很快","example":"My phone battery drains much faster when I deliver food in winter."},{"kind":"phrase","front":"lithium-ion battery","meaning":"锂离子电池","example":"A lithium-ion battery does not perform as well in freezing temperatures."},{"kind":"phrase","front":"deliver power / internal resistance","meaning":"输出电能／内阻","example":"Cold weather can make it harder for a battery to deliver power."},{"kind":"phrase","front":"mount a phone on a bike","meaning":"将手机安装固定在自行车上","example":"I mount my phone on my bike using a phone holder."},{"kind":"phrase","front":"secure something in a holder","meaning":"将某物牢牢固定在支架中","example":"I secure the phone in its holder before I set off."},{"kind":"phrase","front":"handlebars / rear rack","meaning":"车把／后货架","example":"The handlebars and the rear rack are different parts of the bike."},{"kind":"phrase","front":"be exposed to the cold","meaning":"暴露在寒冷环境中","example":"The phone stays exposed to the cold during the whole shift."},{"kind":"phrase","front":"orders keep coming in","meaning":"订单不断涌入","example":"Orders keep coming in even when my phone is nearly dead."},{"kind":"phrase","front":"lose out on earnings","meaning":"损失本可获得的收入","example":"If my phone dies early, I lose out on potential earnings."},{"kind":"phrase","front":"call it a night / cut a shift short","meaning":"今晚收工／提前结束班次","example":"Sometimes I have to cut my shift short because my battery is nearly dead."},{"kind":"phrase","front":"pull up the map","meaning":"打开／调出地图","example":"I pull up the map when I get close to the customer."},{"kind":"phrase","front":"street signs / delivery address","meaning":"路牌／送货地址","example":"The street signs are in Lithuanian, so I check the delivery address carefully."},{"kind":"phrase","front":"know the area / get my bearings","meaning":"熟悉周边／辨清方位","example":"I know the area pretty well, but I still need directions sometimes."},{"kind":"phrase","front":"money is on the line","meaning":"有实际收入得失","example":"During the Friday rush, there is real money on the line."},{"kind":"phrase","front":"run in the background","meaning":"在后台运行","example":"The delivery app sometimes stops alerting me when it runs in the background."},{"kind":"phrase","front":"keep an app in the foreground","meaning":"让应用保持在前台","example":"I sometimes keep the app in the foreground so I do not miss an order."},{"kind":"phrase","front":"the issue is with...","meaning":"问题出在……","example":"I cannot tell whether the issue is with the app or iOS."},{"kind":"phrase","front":"be unfair / let somebody down","meaning":"不公平／让某人失望、掉链子","example":"It feels unfair when the tools I rely on let me down."},{"kind":"sentence","front":"I felt a sharp pain every few seconds. / The pain came and went.","meaning":"","example":""},{"kind":"sentence","front":"The pain isn’t constant. / It comes and goes.","meaning":"","example":""},{"kind":"sentence","front":"My tooth started hurting.","meaning":"","example":""},{"kind":"sentence","front":"I can drink, swallow and chew normally.","meaning":"","example":""},{"kind":"sentence","front":"Rinse my mouth with cold water.","meaning":"","example":""},{"kind":"sentence","front":"The battery becomes less able to deliver power.","meaning":"","example":""},{"kind":"sentence","front":"I mounted the phone on my bike using a holder.","meaning":"","example":""},{"kind":"sentence","front":"It stays mounted outside.","meaning":"","example":""},{"kind":"sentence","front":"It’s the dinner rush, and orders are pouring in.","meaning":"","example":""},{"kind":"sentence","front":"My battery is down to five percent.","meaning":"","example":""},{"kind":"sentence","front":"I use the map to pinpoint the exact location for the last hundred metres.","meaning":"","example":""},{"kind":"phrase","front":"I’ve been + -ing + for...","meaning":"表示某状态持续了多久","example":"My back tooth has been hurting for about a week."},{"kind":"phrase","front":"It comes and goes rather than...","meaning":"表达症状间歇而非持续","example":"The pain comes and goes rather than staying constant."},{"kind":"phrase","front":"Since then, ... has eased off.","meaning":"描述自某时间点后的变化","example":"Since then, the pain has eased off."},{"kind":"phrase","front":"When ..., ... drains much faster.","meaning":"描述某种条件下明显变化","example":"When it’s freezing outside, my phone battery drains much faster."},{"kind":"phrase","front":"I keep ... mounted on ...","meaning":"描述持续固定某设备","example":"I keep my phone mounted on my bike during deliveries."},{"kind":"phrase","front":"By the time ..., ... is down to...","meaning":"到某时点，数值下降到……","example":"By the time I finish three hours of deliveries, my battery may be down to five percent."},{"kind":"paragraph","front":"One of my back teeth has been bothering me for about a week. At first, I had a sharp pain that came and went every few seconds. It got much worse after I ate hot chicken wings and had an ice-cold drink. Since then, the pain has eased off, and I can still chew and swallow normally. But my tooth remains sensitive to cold water, so I’m keeping an eye on it.","meaning":"","example":""},{"kind":"paragraph","front":"I’ve noticed that my phone battery drains much faster when I deliver food on cold nights. I know that low temperatures affect the chemical reactions inside lithium-ion batteries, but it’s still frustrating to watch the battery percentage drop so quickly. My phone stays mounted on my bike for navigation, which means it’s exposed to the cold throughout the shift.","meaning":"","example":""},{"kind":"paragraph","front":"Friday nights can be the busiest time of the week. Orders keep coming in, and I could make good money if I stayed out longer. But after several hours, my battery can be down to five or ten percent. That sometimes forces me to cut my shift short, even while the dinner rush is still in full swing. It feels like I’m missing out on earnings through no fault of my own.","meaning":"","example":""},{"kind":"paragraph","front":"Even after a year of making deliveries, I still need navigation sometimes. I know the area pretty well and can recognize most places on a map, but the street signs are in Lithuanian. The final stretch is especially important, so I usually pull up the map when I’m close to the destination and double-check the exact drop-off point.","meaning":"","example":""},{"kind":"paragraph","front":"What really frustrates me is that the delivery app doesn’t always send notifications when it’s running in the background. Sometimes a new-order alert pops up, and sometimes it doesn’t. I might be checking the map and concentrating on my deliveries, yet still miss an order. I can’t tell whether the issue is with the app or iOS, but it feels unfair when something outside my control affects my earnings.","meaning":"","example":""},{"kind":"phrase","front":"exotic","meaning":"异国情调的；外来的","example":"The market sells exotic spices from several countries."},{"kind":"phrase","front":"spray","meaning":"喷洒；喷雾；喷雾器","example":"Spray a little water on the leaves."},{"kind":"phrase","front":"clunky","meaning":"笨重的；不好用的；操作不灵活的","example":"The old app has a clunky interface."},{"kind":"phrase","front":"woo","meaning":"争取支持；求爱；争取吸引","example":"The company is trying to woo new customers."},{"kind":"phrase","front":"curl","meaning":"卷曲；蜷缩；盘绕","example":"The cat curled up on the sofa."},{"kind":"phrase","front":"embargo","meaning":"禁运；贸易限制","example":"The government imposed an embargo on certain exports."},{"kind":"phrase","front":"handlebars","meaning":"（自行车等的）车把手","example":"I attached the phone holder to my bike's handlebars."},{"kind":"phrase","front":"partial","meaning":"部分的；不完全的；偏袒的","example":"We only received a partial refund."},{"kind":"phrase","front":"outfit","meaning":"全套服装；装备；团队","example":"I packed a warm outfit for the trip."},{"kind":"phrase","front":"dart","meaning":"猛冲；飞奔；飞镖","example":"A squirrel darted across the road."},{"kind":"phrase","front":"prom","meaning":"（学校的）毕业舞会","example":"They went to the school prom together."},{"kind":"phrase","front":"oblivious","meaning":"未察觉的；毫不知情的","example":"He was oblivious to the noise outside."},{"kind":"phrase","front":"expertise","meaning":"专业知识；专长","example":"Her technical expertise helped solve the problem."},{"kind":"phrase","front":"knob","meaning":"圆形把手；旋钮","example":"Turn the knob to lower the temperature."},{"kind":"phrase","front":"reconcile","meaning":"调和；使和解；使一致","example":"It's difficult to reconcile these two conflicting reports."},{"kind":"phrase","front":"confiscate","meaning":"没收；充公","example":"The teacher confiscated the student's phone during the exam."},{"kind":"phrase","front":"dislodge","meaning":"使脱落；移开；驱逐","example":"He tried to dislodge a stone stuck in his shoe."},{"kind":"phrase","front":"residue","meaning":"残留物；残渣","example":"The cleaner removed the sticky residue from the table."},{"kind":"phrase","front":"teleport","meaning":"瞬间移动","example":"If I could teleport, I'd go home for dinner."},{"kind":"phrase","front":"pathology","meaning":"病理学","example":"The laboratory specializes in pathology."},{"kind":"phrase","front":"itinerary","meaning":"旅行行程；日程安排","example":"I planned a seven-day itinerary through Italy."},{"kind":"phrase","front":"ante","meaning":"赌注；预付款；（习语）投入或门槛","example":"The company had to up the ante to compete."},{"kind":"phrase","front":"exert","meaning":"施加；发挥（影响、力量）","example":"The new policy may exert pressure on small businesses."},{"kind":"phrase","front":"smug","meaning":"自鸣得意的；沾沾自喜的","example":"He looked smug after winning the argument."},{"kind":"phrase","front":"draw","meaning":"画；拉；吸引；抽出","example":"The exhibition drew visitors from across the country."},{"kind":"phrase","front":"weep","meaning":"哭泣；流泪；（液体）渗出","example":"She began to weep when she heard the news."},{"kind":"phrase","front":"scone","meaning":"司康饼","example":"I ordered a scone with tea at the café."},{"kind":"phrase","front":"proofread","meaning":"校对；检查拼写和语法错误","example":"Please proofread the report before submitting it."},{"kind":"phrase","front":"downside","meaning":"不足之处、负面影响｜适用场景：日常口语，非常高频","example":"The downside of living so far from campus is the long commute."},{"kind":"phrase","front":"drawback","meaning":"缺点、不足｜适用场景：计划、方案、产品、选择","example":"One drawback of this plan is that it leaves us very little flexibility."},{"kind":"phrase","front":"weakness","meaning":"弱点、薄弱之处｜适用场景：人、能力、系统","example":"The biggest weakness of the system is its unreliable internet connection."},{"kind":"phrase","front":"shortcoming","meaning":"缺点、不足之处｜适用场景：人的性格、能力、表现","example":"She knows her shortcomings and is working to improve them."},{"kind":"phrase","front":"flaw","meaning":"缺陷、瑕疵｜适用场景：设计、逻辑、性格","example":"There's a serious flaw in the argument."},{"kind":"phrase","front":"defect","meaning":"缺陷、故障｜适用场景：产品、制造、技术","example":"The manufacturer recalled the product because of a safety defect."},{"kind":"phrase","front":"limitation","meaning":"局限性、不足｜适用场景：方法、技术、研究","example":"One limitation of this study is its small sample size."},{"kind":"phrase","front":"disadvantage","meaning":"劣势、不利之处｜适用场景：比较不同选择","example":"The main disadvantage of taking the bus is that it takes much longer."},{"kind":"phrase","front":"imperfection","meaning":"不完美之处、瑕疵｜适用场景：人、事物、作品","example":"The handmade bowl has a few small imperfections, which give it character."},{"kind":"phrase","front":"negative aspect","meaning":"不太好的方面、负面之处｜适用场景：通用、中性","example":"One negative aspect of the job is the unpredictable schedule."},{"kind":"phrase","front":"handfuls of people","meaning":"少量的人；几小群人","example":"① Only handfuls of volunteers came to the meeting.\n只有零星几名志愿者参加会议。\n\n② Handfuls of hikers reached the summit before sunrise.\n只有几小批徒步者在日出前登顶。"},{"kind":"phrase","front":"arduous crossing","meaning":"艰难的横渡；艰苦的穿越","example":"① The arduous crossing took several weeks.\n这次艰难的横渡花了几个星期。\n\n② We prepared carefully for the arduous mountain crossing.\n我们为艰险的山地穿越做了充分准备。"},{"kind":"phrase","front":"consume something voraciously","meaning":"如饥似渴地阅读、观看或消费某物","example":"① Readers consumed the new biography voraciously.\n读者如饥似渴地阅读这本新传记。\n\n② Investors consumed every update voraciously.\n投资者迫切地关注每一次最新消息。"},{"kind":"phrase","front":"seemingly endless","meaning":"似乎无穷无尽的","example":"① The seemingly endless queue moved slowly.\n看似排不到头的队伍缓慢前进。\n\n② They drove across seemingly endless plains.\n他们开车穿过仿佛无边无际的平原。"},{"kind":"phrase","front":"stretch out for miles","meaning":"绵延数英里；向远方延伸","example":"① The coastline stretches out for miles.\n海岸线向远处绵延数英里。\n\n② A long valley stretched out ahead of us.\n一条长长的山谷在我们面前延伸。"},{"kind":"phrase","front":"a symbol of / an object of / a source of","meaning":"……的象征／对象／来源；并列名词结构","example":"① The bridge became a symbol of progress.\n这座桥成为进步的象征。\n\n② The city is both an object of fascination and a source of opportunity.\n这座城市既令人着迷，也蕴含着机遇。"},{"kind":"phrase","front":"the subsequent two hundred years","meaning":"此后的两百年；subsequent 表示随后发生的","example":"① The subsequent years brought rapid changes.\n随后的几年发生了迅速变化。\n\n② Over the subsequent decade, prices doubled.\n在之后的十年里，价格翻了一番。"},{"kind":"phrase","front":"provide the lubrication (for) [figurative]","meaning":"为……提供润滑作用、促进顺畅运转；比喻用法","example":"① Credit provides the lubrication for commerce.\n信贷为商业活动提供了润滑作用。\n\n② Trust can provide the lubrication for difficult negotiations.\n信任可以使艰难的谈判更顺畅。"},{"kind":"phrase","front":"ripple across the globe","meaning":"影响波及全球；逐渐扩散到世界各地","example":"① The financial shock rippled across the globe.\n金融冲击波及全球。\n\n② The new technology rippled across the globe within years.\n新技术在几年内传播到世界各地。"},{"kind":"phrase","front":"aristocratic pedigree","meaning":"贵族出身；显赫的家世","example":"① The politician had an aristocratic pedigree.\n那名政治人物出身贵族。\n\n② Her ideas mattered more than her family's aristocratic pedigree.\n她的思想比家族的贵族背景更重要。"},{"kind":"phrase","front":"outright","meaning":"彻底的；公开而明确的；完全地","example":"① The disagreement turned into outright conflict.\n分歧演变成公开冲突。\n\n② The company rejected the proposal outright.\n公司断然拒绝了这项提议。"},{"kind":"phrase","front":"fecund","meaning":"肥沃的；多产的；富于创造力的（书面）","example":"① The valley has fecund soil.\n这片山谷的土壤十分肥沃。\n\n② It was a fecund period for scientific discovery.\n那是科学发现层出不穷的时期。"},{"kind":"phrase","front":"charity","meaning":"慈善；施舍；善意援助","example":"① The family survived partly through charity.\n这家人部分依靠慈善救济维生。\n\n② The organization relies on donations and charity.\n该机构依靠捐款与慈善资助。"},{"kind":"phrase","front":"population density","meaning":"人口密度","example":"① Population density is much higher in cities.\n城市的人口密度高得多。\n\n② The map compares population density across regions.\n这张地图比较了各地区的人口密度。"},{"kind":"phrase","front":"sparsely populated","meaning":"人口稀少的","example":"① The northern region is sparsely populated.\n北部地区人口稀少。\n\n② Sparsely populated areas often have limited bus services.\n人口稀少的地区通常公交服务有限。"},{"kind":"phrase","front":"induce somebody to do something","meaning":"诱使、促使或劝使某人做某事","example":"① Higher wages induced workers to move west.\n更高工资促使工人向西迁移。\n\n② The discount induced more customers to sign up.\n折扣促使更多客户注册。"},{"kind":"phrase","front":"indentured labor","meaning":"契约劳工；限期劳动服务","example":"① Indentured labor helped fill the labor shortage.\n契约劳工帮助缓解了劳动力短缺。\n\n② The historian studied contracts for indentured labor.\n历史学家研究了契约劳工合同。"},{"kind":"phrase","front":"treacherous journey","meaning":"危险重重的旅途","example":"① The crew survived a treacherous journey.\n船员熬过了一段险象环生的旅程。\n\n② Ice made the mountain journey treacherous.\n冰雪让山路变得危险。"},{"kind":"phrase","front":"decidedly better","meaning":"明显更好；确实更好","example":"① The revised plan is decidedly better.\n修改后的计划明显更好。\n\n② She felt decidedly better after resting.\n休息后她感觉明显好转。"},{"kind":"phrase","front":"contingent on","meaning":"取决于；以……为条件","example":"① Approval is contingent on passing the inspection.\n批准以通过检查为前提。\n\n② The trip is contingent on the weather.\n这次旅行能否成行取决于天气。"},{"kind":"phrase","front":"egalitarian","meaning":"平等主义的；主张人人平等的","example":"① They wanted a more egalitarian society.\n他们希望建立更加平等的社会。\n\n② The organization has an egalitarian culture.\n该组织具有平等主义文化。"},{"kind":"phrase","front":"ghastly antithesis","meaning":"可怕的反面；截然相反的恐怖景象","example":"① The reality was the ghastly antithesis of their ideal.\n现实是他们理想中令人不安的反面。\n\n② The luxurious palace stood beside its ghastly antithesis: a slum.\n豪华宫殿旁边就是可怕的反面：贫民窟。"},{"kind":"phrase","front":"trappings","meaning":"（某种制度、地位、生活方式的）外在配套与象征","example":"① The office had all the trappings of success.\n办公室具备成功企业的各种外在标志。\n\n② The settlement lacked the trappings of a modern town.\n这个定居点缺少现代城镇应有的配套。"},{"kind":"phrase","front":"resort to barter","meaning":"不得不采取以物易物的方式","example":"① Without cash, traders resorted to barter.\n没有现金时，商人只得以物易物。\n\n② The villagers resorted to barter during the crisis.\n危机期间村民不得不交换物品。"},{"kind":"phrase","front":"vendor","meaning":"卖方；小贩；供应商","example":"① The vendor refused to accept the damaged item.\n卖家拒绝收下损坏的物品。\n\n② We compared prices from three vendors.\n我们比较了三家供应商的报价。"},{"kind":"phrase","front":"lumber","meaning":"木材（主要为美式英语）","example":"① The company shipped lumber overseas.\n公司向海外运输木材。\n\n② Rising lumber costs pushed up construction prices.\n木材成本上涨推高了建筑价格。"},{"kind":"phrase","front":"a vital necessity for","meaning":"对……至关重要的必需品、必要条件","example":"① Clean water is a vital necessity for the village.\n清洁饮水对这个村庄至关重要。\n\n② Reliable transport was a vital necessity for trade.\n可靠运输是贸易的必要条件。"},{"kind":"phrase","front":"perennial","meaning":"长期存在的；反复出现的","example":"① Housing shortages are a perennial problem.\n住房短缺是长期存在的问题。\n\n② It is a perennial debate among economists.\n这是经济学家反复讨论的争议。"},{"kind":"phrase","front":"time and again","meaning":"一再；反复地","example":"① Time and again, the same issue returned.\n同一个问题一再出现。\n\n② She warned us time and again about the risks.\n她反复提醒我们这些风险。"},{"kind":"phrase","front":"smother","meaning":"压制、扼杀（思想、企图等）；使窒息","example":"① Excessive rules can smother innovation.\n过多规定可能扼杀创新。\n\n② He tried to smother his anger.\n他试图压抑自己的愤怒。"},{"kind":"phrase","front":"egregious source of rancor","meaning":"极其严重的怨恨来源；egregious=恶劣的，rancor=积怨","example":"① The unfair rule became a source of rancor.\n这项不公规定成为积怨的来源。\n\n② The egregious abuse of power sparked lasting rancor.\n恶劣的滥权行为引发了长期怨恨。"},{"kind":"phrase","front":"upheaval","meaning":"剧变；动荡","example":"① The reforms caused political upheaval.\n改革引发政治动荡。\n\n② The industry went through a period of upheaval.\n该行业经历了一段剧变时期。"},{"kind":"phrase","front":"trailblazing work","meaning":"开创性工作或著作","example":"① Her trailblazing work changed the field.\n她开创性的研究改变了这一领域。\n\n② The scientist published a trailblazing paper.\n这位科学家发表了一篇开创性论文。"},{"kind":"phrase","front":"figuratively and literally","meaning":"既是比喻意义上，也是字面意义上","example":"① The discovery changed the landscape, figuratively and literally.\n这一发现从比喻和字面两方面改变了局面。\n\n② The storm shook the town, figuratively and literally.\n风暴在实际和象征意义上都震动了这座城镇。"},{"kind":"phrase","front":"the inquiry of intellectuals","meaning":"知识分子的探索、研究或探究","example":"① The inquiry of intellectuals shifted toward economics.\n知识分子的探索转向经济学。\n\n② Scientific inquiry requires evidence.\n科学探究需要证据。"},{"kind":"phrase","front":"boom and flounder","meaning":"时而繁荣、时而陷入困境","example":"① Some businesses boom while others flounder.\n有些企业繁荣，有些却陷入困境。\n\n② The startup floundered after demand collapsed.\n需求崩溃后，这家初创公司陷入困境。"},{"kind":"phrase","front":"alchemy","meaning":"炼金术；将事物神奇地转化的做法","example":"① Medieval scholars studied alchemy.\n中世纪学者研究炼金术。\n\n② There is no financial alchemy that removes all risk.\n不存在能够消除一切风险的金融魔法。"},{"kind":"phrase","front":"pledge land to a bank","meaning":"将土地向银行抵押、担保","example":"① The owner pledged land to the bank for a loan.\n业主以土地向银行抵押贷款。\n\n② They refused to pledge their family home as collateral.\n他们拒绝用家庭住宅作抵押。"},{"kind":"phrase","front":"inherent value","meaning":"内在价值；固有价值","example":"① The asset may have inherent value.\n这项资产可能具有内在价值。\n\n② We must distinguish price from inherent value.\n我们必须区分价格与内在价值。"},{"kind":"phrase","front":"throttle the economy","meaning":"限制、扼制经济活动","example":"① A credit crunch can throttle the economy.\n信贷紧缩可能扼制经济。\n\n② High transport costs throttle regional growth.\n高运输成本限制地区增长。"},{"kind":"phrase","front":"prophetic in one's diagnosis","meaning":"在判断或分析上有先见之明","example":"① Her diagnosis of the crisis proved prophetic.\n她对危机的判断事后证明具有先见之明。\n\n② The analyst was prophetic in warning about debt.\n这位分析师对债务风险的警告很有远见。"},{"kind":"phrase","front":"forerunner","meaning":"先驱；前身；预兆","example":"① The early machine was a forerunner of the computer.\n这台早期机器是计算机的前身。\n\n② The group was a forerunner of the modern association.\n这个团体是现代协会的前身。"},{"kind":"phrase","front":"grasp","meaning":"理解、领会；抓住","example":"① It took me a while to grasp the concept.\n我花了一会儿才理解这个概念。\n\n② The investors failed to grasp the full risk.\n投资者未能理解全部风险。"},{"kind":"phrase","front":"extraordinarily farsighted","meaning":"极有远见的","example":"① The policy was extraordinarily farsighted.\n这项政策极具前瞻性。\n\n② It was a farsighted investment in education.\n这是一项具有远见的教育投资。"},{"kind":"phrase","front":"disseminate","meaning":"传播、广泛散布（信息、思想）","example":"① The institute disseminated its findings online.\n研究所在线传播了研究发现。\n\n② Social media can disseminate rumors quickly.\n社交媒体能迅速传播谣言。"},{"kind":"phrase","front":"backwater","meaning":"闭塞落后的地方；不受重视的领域","example":"① The town was once an economic backwater.\n这座小镇曾经经济落后。\n\n② The subject was treated as an academic backwater.\n这一学科曾不受学术界重视。"},{"kind":"phrase","front":"remedy the situation","meaning":"补救、改善局面","example":"① The government acted to remedy the situation.\n政府采取行动补救局面。\n\n② More staff would help remedy the shortage.\n增加人手有助于缓解短缺。"},{"kind":"phrase","front":"alleviate","meaning":"缓解（痛苦、贫困、压力、短缺）","example":"① The policy aims to alleviate poverty.\n这项政策旨在缓解贫困。\n\n② Rest may alleviate the discomfort.\n休息可能减轻不适。"},{"kind":"phrase","front":"detriment","meaning":"损害；不利影响，常见 to one's detriment","example":"① He ignored the advice to his own detriment.\n他忽视建议，结果损害了自身利益。\n\n② The change benefited some people to the detriment of others.\n这项变化使一些人受益，却损害了另一些人的利益。"},{"kind":"phrase","front":"muster","meaning":"筹集；集结；鼓起（勇气、力量）","example":"① The town could not muster enough money.\n镇上筹集不到足够的钱。\n\n② She mustered the courage to speak.\n她鼓起勇气发言。"},{"kind":"phrase","front":"befriend","meaning":"与……结交；友善待人","example":"① He befriended a local journalist.\n他结识了一位当地记者。\n\n② She befriended her new classmate.\n她与新同学交上了朋友。"},{"kind":"phrase","front":"discordant","meaning":"不协调的；意见冲突的；刺耳的","example":"① The committee heard discordant opinions.\n委员会听到了彼此冲突的意见。\n\n② Discordant voices filled the hall.\n大厅里充满了不协调的声音。"},{"kind":"phrase","front":"rub up against","meaning":"碰到、触及并与……发生冲突","example":"① The proposal rubbed up against existing rules.\n这项提议与现有规则发生抵触。\n\n② Their ambitions rubbed up against political reality.\n他们的雄心与政治现实发生冲突。"},{"kind":"phrase","front":"be bogged down in","meaning":"陷入……而难以前进","example":"① The project was bogged down in paperwork.\n项目陷入文书工作而停滞。\n\n② Negotiations became bogged down in details.\n谈判陷入细节争论中。"},{"kind":"phrase","front":"crop up","meaning":"突然出现；不断冒出来","example":"① New problems crop up every week.\n每周都有新问题冒出来。\n\n② Small shops cropped up near the station.\n车站附近陆续出现小商店。"},{"kind":"phrase","front":"alien to","meaning":"对……陌生的；与……格格不入的","example":"① The custom was alien to the visitors.\n这种习俗让游客感到陌生。\n\n② That approach was alien to the old elite.\n旧精英阶层对这种做法感到格格不入。"},{"kind":"phrase","front":"foreclose on","meaning":"取消抵押品赎回权，依法收回抵押资产","example":"① The bank may foreclose on the property.\n银行可能依法收回该抵押房产。\n\n② Many owners feared foreclosure during the crisis.\n危机期间许多业主担心遭到止赎。"},{"kind":"phrase","front":"divergent","meaning":"分歧的；不同方向的","example":"① The two regions have divergent interests.\n这两个地区的利益存在分歧。\n\n② The forecasts show divergent trends.\n预测显示不同方向的趋势。"},{"kind":"phrase","front":"collateral","meaning":"贷款抵押品；担保物","example":"① The bank accepted land as collateral.\n银行接受土地作为抵押品。\n\n② He used his house as collateral for the loan.\n他用自己的房子为贷款提供担保。"},{"kind":"phrase","front":"agitated","meaning":"焦虑不安的；激动的","example":"① She became agitated by the bad news.\n坏消息令她焦虑不安。\n\n② The crowd grew increasingly agitated.\n人群变得越来越激动。"},{"kind":"phrase","front":"redeemable","meaning":"可兑换的；可赎回的","example":"① The note was redeemable for silver.\n这种票据可以兑换白银。\n\n② The voucher is redeemable at selected stores.\n代金券可在指定商店兑换。"},{"kind":"phrase","front":"swiftly","meaning":"迅速地；很快","example":"① The government acted swiftly.\n政府迅速采取行动。\n\n② Prices fell swiftly after the announcement.\n公告之后价格迅速下跌。"},{"kind":"phrase","front":"ordeal","meaning":"痛苦经历；严峻考验","example":"① The long trial was an ordeal for the family.\n漫长的审判对家人是一场煎熬。\n\n② They survived the ordeal together.\n他们共同熬过了这段磨难。"},{"kind":"phrase","front":"imperial","meaning":"帝国的；帝国主义的","example":"① The policy served imperial interests.\n这项政策服务于帝国利益。\n\n② The museum displays artifacts from the imperial era.\n博物馆展示帝国时期的文物。"},{"kind":"phrase","front":"fervent","meaning":"热烈的；坚定而强烈的","example":"① He was a fervent supporter of reform.\n他是改革的坚定支持者。\n\n② The proposal met with fervent opposition.\n该提案遭到强烈反对。"},{"kind":"phrase","front":"affluence","meaning":"富裕；丰裕","example":"① The city enjoyed rising affluence.\n这座城市日益富裕。\n\n② Affluence does not guarantee happiness.\n富裕不保证幸福。"},{"kind":"phrase","front":"noxious","meaning":"有害的；有毒的；恶劣的","example":"① The factory released noxious fumes.\n工厂排放有毒烟气。\n\n② The policy had noxious social effects.\n这项政策产生了有害的社会影响。"},{"kind":"phrase","front":"speculation","meaning":"投机；推测（视语境）","example":"① Land speculation drove up prices.\n土地投机推高了价格。\n\n② There was widespread speculation about the decision.\n人们对这项决定进行了广泛猜测。"},{"kind":"phrase","front":"parcel out the land","meaning":"将土地分割、划拨分配","example":"① The owner parceled out the land to farmers.\n地主把土地分块分给农民。\n\n② They parceled out the estate among the heirs.\n他们将地产分给各位继承人。"},{"kind":"phrase","front":"fringes","meaning":"边缘地区；边缘地带","example":"① They settled on the fringes of the city.\n他们定居在城市边缘地带。\n\n② The idea remained on the fringes of politics.\n这种观念一直处于政治边缘。"},{"kind":"phrase","front":"rapacious","meaning":"贪婪掠夺的；贪得无厌的","example":"① Rapacious investors sought quick profits.\n贪婪的投资者追逐短期利润。\n\n② The regime was criticized for rapacious exploitation.\n该政权因贪婪掠夺遭到批评。"},{"kind":"phrase","front":"regiment","meaning":"（军队的）团；军团","example":"① The regiment marched north.\n这个团向北进军。\n\n② He joined an infantry regiment.\n他加入了一个步兵团。"},{"kind":"phrase","front":"enamored with / of","meaning":"迷恋；对……着迷","example":"① She was enamored with the idea of travel.\n她对旅行的想法着迷。\n\n② Investors became enamored of the new technology.\n投资者迷上了这项新技术。"},{"kind":"phrase","front":"triumph","meaning":"获胜；取得重大成功","example":"① The allies finally triumphed.\n盟军最终取得胜利。\n\n② The team triumphed despite the setbacks.\n球队尽管遭遇挫折仍取得胜利。"},{"kind":"phrase","front":"cement","meaning":"巩固、加强（关系、地位、成果）","example":"① The victory cemented his reputation.\n胜利巩固了他的声誉。\n\n② The deal cemented ties between the companies.\n这笔交易加强了两家公司的联系。"},{"kind":"phrase","front":"cede","meaning":"割让；让出（土地、权利、控制权）","example":"① The state was forced to cede territory.\n该国被迫割让领土。\n\n② The founder refused to cede control of the company.\n创始人拒绝交出公司控制权。"},{"kind":"phrase","front":"benign","meaning":"良性的；温和无害的；善意的","example":"① The doctor said the growth was benign.\n医生说这个肿块是良性的。\n\n② The policy reflected benign neglect rather than active support.\n这项政策体现的是善意忽视，而非积极支持。"},{"kind":"phrase","front":"flagrant","meaning":"公然的；明目张胆的（违规等）","example":"① It was a flagrant violation of the rules.\n这是公然违反规则的行为。\n\n② The company faced criticism for flagrant misconduct.\n公司因明目张胆的不当行为受到批评。"},{"kind":"phrase","front":"placate","meaning":"安抚；平息……的不满","example":"① The manager tried to placate angry residents.\n管理员试图安抚愤怒的住户。\n\n② A small refund did little to placate customers.\n少量退款并未让顾客平息怒气。"},{"kind":"phrase","front":"curtail","meaning":"削减；限制（权利、活动、开支）","example":"① The authorities curtailed travel rights.\n当局限制了出行权利。\n\n② The firm curtailed spending during the downturn.\n公司在衰退期间削减支出。"},{"kind":"phrase","front":"quell","meaning":"平息；镇压（骚乱、不满等）","example":"① The police tried to quell the unrest.\n警方试图平息骚乱。\n\n② The statement failed to quell public concern.\n声明未能消除公众担忧。"},{"kind":"phrase","front":"unheeded","meaning":"未被理会的；未被采纳的","example":"① His warnings went unheeded.\n他的警告无人理会。\n\n② The proposal remained unheeded for years.\n这项提议多年来未获采纳。"},{"kind":"phrase","front":"grievance","meaning":"不满；申诉；委屈","example":"① Workers filed a formal grievance.\n工人提出了正式申诉。\n\n② The policy became a major public grievance.\n这项政策成为公众严重不满的来源。"},{"kind":"phrase","front":"tease apart","meaning":"仔细区分；梳理复杂因素","example":"① It is hard to tease apart cause and effect.\n很难仔细区分因果关系。\n\n② The report teases apart several sources of risk.\n报告梳理了几种不同风险来源。"},{"kind":"phrase","front":"irrevocably","meaning":"不可撤销地；不可逆转地","example":"① Their fates became irrevocably linked.\n他们的命运不可逆转地联系在一起。\n\n② The decision irrevocably changed the industry.\n这一决定不可逆转地改变了行业。"},{"kind":"phrase","front":"enumerate","meaning":"逐项列举；枚举","example":"① The report enumerates the main risks.\n报告逐项列出了主要风险。\n\n② Please enumerate the changes you recommend.\n请逐项列出你建议的修改。"},{"kind":"phrase","front":"sanctity","meaning":"神圣性；不可侵犯性","example":"① The constitution protects the sanctity of private property.\n宪法保护私人财产的不可侵犯性。\n\n② They debated the sanctity of the agreement.\n他们讨论了该协议的不可侵犯性。"},{"kind":"phrase","front":"oddity","meaning":"奇特的人或事；异类","example":"① The system was once regarded as an oddity.\n这种制度曾被视为异类。\n\n② The old building is an architectural oddity.\n这栋老建筑是一个建筑奇观。"},{"kind":"phrase","front":"rowdy","meaning":"吵闹的；喧嚣的；粗野的","example":"① The pub became rowdy after midnight.\n午夜以后酒吧变得吵闹。\n\n② A rowdy crowd gathered outside.\n一群喧闹的人聚集在外面。"},{"kind":"phrase","front":"temperance","meaning":"禁酒；节制，常见 temperance movement","example":"① The temperance movement opposed alcohol sales.\n禁酒运动反对出售酒类。\n\n② She supported temperance campaigns in the city.\n她支持这座城市的禁酒活动。"},{"kind":"phrase","front":"loom over","meaning":"耸立在……上方；（威胁）笼罩着","example":"① The castle loomed over the valley.\n城堡高耸于山谷之上。\n\n② Debt problems loomed over the economy.\n债务问题笼罩着经济。"},{"kind":"phrase","front":"grubby","meaning":"脏兮兮的；肮脏的","example":"① His hands were grubby after work.\n下班后他的双手脏兮兮的。\n\n② They stayed in a grubby old hotel.\n他们住在一家肮脏的老酒店。"},{"kind":"phrase","front":"impoverished","meaning":"贫困的；被耗尽的","example":"① Aid reached impoverished neighborhoods.\n援助送达贫困社区。\n\n② Years of conflict left the region impoverished.\n多年冲突使该地区陷入贫困。"},{"kind":"phrase","front":"onwards to","meaning":"继续前往；进一步到达","example":"① The goods traveled onwards to the capital.\n货物继续运往首都。\n\n② We walked onwards to the next village.\n我们继续步行前往下一个村庄。"},{"kind":"phrase","front":"incendiary","meaning":"煽动性的；容易激起愤怒的；也指燃烧性的","example":"① The minister made an incendiary speech.\n部长发表了一场煽动性演讲。\n\n② The headline used incendiary language.\n标题使用了极具挑衅性的措辞。"},{"kind":"phrase","front":"inflammatory","meaning":"煽动性的；易引发强烈反应的；医学上为炎症性的","example":"① The article contained inflammatory claims.\n文章包含煽动性言论。\n\n② The speaker avoided inflammatory remarks.\n演讲者避免使用挑衅性言辞。"},{"kind":"phrase","front":"belligerent","meaning":"好战的；挑衅的；攻击性的","example":"① The country adopted a more belligerent tone.\n该国采用了更加好战的语气。\n\n② A belligerent customer shouted at the staff.\n一名咄咄逼人的顾客对员工大喊。"},{"kind":"phrase","front":"hawker","meaning":"沿街叫卖的小贩","example":"① Street hawkers sold newspapers outside.\n街头小贩在外面售卖报纸。\n\n② Hawkers gathered near the station.\n小贩聚集在车站附近。"},{"kind":"phrase","front":"fiery provocation","meaning":"激烈挑衅；充满火药味的煽动","example":"① The speech was full of fiery provocation.\n演讲充满激烈挑衅。\n\n② He responded calmly to the fiery provocation.\n面对激烈挑衅，他冷静回应。"},{"kind":"phrase","front":"impasse","meaning":"僵局；无法推进的局面","example":"① The talks reached an impasse.\n谈判陷入僵局。\n\n② Both parties sought a way out of the impasse.\n双方试图寻找打破僵局的办法。"},{"kind":"phrase","front":"embroiled in","meaning":"卷入（争端、困境、丑闻）","example":"① The company became embroiled in a lawsuit.\n公司卷入一场诉讼。\n\n② He was embroiled in a political dispute.\n他卷入了政治争端。"},{"kind":"phrase","front":"expropriate","meaning":"征收、征用或剥夺财产","example":"① The state expropriated the land for a railway.\n国家为修建铁路征用了这块土地。\n\n② Critics warned that the measure could expropriate private wealth.\n批评者警告该措施可能剥夺私人财富。"},{"kind":"phrase","front":"hoard","meaning":"囤积（物资、财富、信息）","example":"① Investors hoarded cash during the panic.\n恐慌期间投资者囤积现金。\n\n② The landlord was accused of hoarding land.\n地主被指责囤积土地。"},{"kind":"phrase","front":"protracted","meaning":"旷日持久的；拖延很久的","example":"① The country entered a protracted recession.\n这个国家陷入漫长衰退。\n\n② A protracted legal dispute delayed the project.\n旷日持久的法律争端拖延了项目。"},{"kind":"phrase","front":"ripple through","meaning":"（影响）逐渐波及、传遍","example":"① The shock rippled through financial markets.\n冲击波及金融市场。\n\n② The news rippled through the town.\n消息迅速传遍小镇。"},{"kind":"phrase","front":"devoutly","meaning":"虔诚地；坚定地（多修饰 religious）","example":"① His parents were devoutly religious.\n他的父母信仰十分虔诚。\n\n② She was brought up in a devoutly religious home.\n她在宗教信仰虔诚的家庭长大。"},{"kind":"phrase","front":"stint","meaning":"一段工作、任职或服役时期","example":"① He did a short stint at a newspaper.\n他曾在报社短暂工作。\n\n② After a stint abroad, she returned home.\n在国外待了一段时间后，她回国了。"},{"kind":"phrase","front":"intermittent","meaning":"断断续续的；间歇性的","example":"① He found only intermittent work.\n他只能找到断断续续的工作。\n\n② Intermittent rain slowed the hike.\n间歇性的降雨拖慢了徒步行程。"},{"kind":"phrase","front":"lucrative","meaning":"利润丰厚的；赚钱的","example":"① Software consulting can be lucrative.\n软件咨询可能利润丰厚。\n\n② Not every growing business is lucrative.\n并不是每家增长中的企业都赚钱。"},{"kind":"phrase","front":"germinate","meaning":"萌芽；开始形成（思想、计划）","example":"① The idea began to germinate years earlier.\n这个想法早在多年前就开始萌芽。\n\n② Seeds germinate faster in warm soil.\n种子在温暖土壤中发芽更快。"},{"kind":"phrase","front":"It was not until ... that ...","meaning":"直到……才……；强调句型","example":"① It was not until midnight that the train arrived.\n直到午夜火车才抵达。\n\n② It was not until she explained it that I understood.\n直到她解释后我才明白。"},{"kind":"phrase","front":"destitution","meaning":"赤贫；一贫如洗","example":"① The crisis pushed families into destitution.\n危机让一些家庭陷入赤贫。\n\n② The charity helps people facing destitution.\n该慈善机构帮助面临极端贫困的人们。"},{"kind":"phrase","front":"fruits of progress","meaning":"进步成果；发展带来的收益","example":"① Not everyone shared in the fruits of progress.\n并非所有人都分享到发展成果。\n\n② Workers argued for a fair share of the fruits of progress.\n工人主张公平分享进步成果。"},{"kind":"phrase","front":"vacuum up","meaning":"大量吸走；攫取（利润、资源等）","example":"① A few firms vacuumed up most of the profits.\n少数公司攫取了大部分利润。\n\n② The fund vacuumed up available capital.\n该基金吸走了大量可用资本。"},{"kind":"phrase","front":"immiserating","meaning":"使人越来越贫困的；致贫的（较少见）","example":"① The immiserating crisis hit working families hardest.\n这场致贫危机对工薪家庭打击最大。\n\n② They criticized the policy as immiserating.\n他们批评该政策使民众陷入贫困。"},{"kind":"phrase","front":"pepper an era with","meaning":"在某时期频繁出现、散布于其间","example":"① Violent strikes peppered the era.\n那个时代暴力罢工频繁发生。\n\n② Unexpected scandals peppered his career.\n他的职业生涯中丑闻接连出现。"},{"kind":"phrase","front":"a frenzy for land","meaning":"土地抢购狂热；对土地的疯狂追逐","example":"① A frenzy for land pushed prices higher.\n土地抢购狂潮推高了价格。\n\n② Speculators joined a frenzy for cheap plots.\n投机者纷纷加入廉价土地抢购热潮。"},{"kind":"phrase","front":"blunt","meaning":"直截了当的；生硬的；钝的","example":"① She gave a blunt assessment of the risks.\n她直截了当地评估了风险。\n\n② The proposal was a blunt solution to a complex problem.\n这项提案是对复杂问题的简单粗暴的解决办法。"},{"kind":"phrase","front":"preacher","meaning":"传教士；布道者；爱说教的人","example":"① The preacher addressed a large crowd.\n传教士向大批听众演讲。\n\n② He sounded more like a preacher than an economist.\n他听起来更像布道者而非经济学家。"},{"kind":"phrase","front":"spasm","meaning":"痉挛；突发而短暂的剧烈震荡","example":"① A financial spasm shook the banking system.\n一场金融震荡冲击了银行体系。\n\n② He felt a sudden muscle spasm.\n他感到肌肉突然痉挛。"},{"kind":"phrase","front":"aftermath","meaning":"（灾难、事件的）后果、余波","example":"① The city struggled in the aftermath of the flood.\n洪灾后这座城市艰难恢复。\n\n② Markets remained volatile in the aftermath of the crisis.\n危机余波下市场依然波动。"},{"kind":"phrase","front":"frenetic","meaning":"狂热而忙乱的；高速紧张的","example":"① The campaign entered a frenetic final week.\n竞选进入忙乱紧张的最后一周。\n\n② The office was frenetic before the deadline.\n截止日期前办公室忙得不可开交。"},{"kind":"phrase","front":"astound","meaning":"使震惊；使大为惊讶","example":"① The results astounded the researchers.\n结果让研究人员大吃一惊。\n\n② The scale of the project astounded visitors.\n项目规模令参观者惊叹。"},{"kind":"phrase","front":"gargantuan","meaning":"巨大的；庞大得惊人的","example":"① The firm accumulated a gargantuan debt.\n公司积累了巨额债务。\n\n② A gargantuan task lay ahead.\n面前是一项异常艰巨的任务。"},{"kind":"phrase","front":"diatribe","meaning":"长篇激烈抨击；痛斥文章","example":"① He published a diatribe against corruption.\n他发表了一篇痛斥腐败的文章。\n\n② The meeting turned into a diatribe against the policy.\n会议变成了对该政策的长篇痛批。"},{"kind":"phrase","front":"incarceration","meaning":"监禁；关押","example":"① He wrote about his brief incarceration.\n他写下自己短暂被关押的经历。\n\n② The report examined rates of incarceration.\n报告研究了监禁率。"},{"kind":"phrase","front":"dissent from","meaning":"不同意（观点、裁决）；持异议","example":"① Some economists dissent from that conclusion.\n一些经济学家不同意这一结论。\n\n② The judge dissented from the majority opinion.\n法官对多数意见持异议。"},{"kind":"phrase","front":"lucid","meaning":"表达清楚的；易于理解的；头脑清醒的","example":"① Her explanation was lucid and concise.\n她的解释清晰而简洁。\n\n② The author gave a lucid account of the crisis.\n作者清楚地讲述了这场危机。"},{"kind":"phrase","front":"underbelly","meaning":"阴暗面；隐蔽的薄弱部分","example":"① The film shows the city's dark underbelly.\n影片揭示了这座城市的阴暗面。\n\n② The scandal exposed the industry's underbelly.\n丑闻暴露了该行业的阴暗面。"},{"kind":"phrase","front":"desist from","meaning":"停止（不当或令人厌恶的行为）；正式用语","example":"① The court ordered them to desist from harassment.\n法院命令他们停止骚扰。\n\n② He refused to desist from spreading rumors.\n他拒绝停止散布谣言。"},{"kind":"phrase","front":"crusade","meaning":"长期而坚定的改革运动；（历史）十字军东征","example":"① She launched a crusade against corruption.\n她发起了反腐运动。\n\n② His crusade for fair taxation attracted supporters.\n他争取公平税收的运动吸引了支持者。"},{"kind":"phrase","front":"snappily","meaning":"利落地；俏皮简洁地（如命名、表达）","example":"① The campaign was snappily named.\n这场运动的名字简短又醒目。\n\n② She summed up the problem snappily.\n她简洁有力地概括了问题。"},{"kind":"phrase","front":"stoppage","meaning":"停工；中断；（英式）伤停补时等","example":"① Work stoppages disrupted production.\n停工打断了生产。\n\n② The strike caused a two-day stoppage.\n罢工造成两天停工。"},{"kind":"phrase","front":"strike","meaning":"罢工；击打；突然发生（多义词）","example":"① Workers voted to strike next week.\n工人投票决定下周罢工。\n\n② A severe storm struck the coast.\n一场强烈风暴袭击了海岸。"},{"kind":"phrase","front":"leech (off) / be leeched by","meaning":"像水蛭一样榨取；寄生式攫取","example":"① Middlemen leeched profits from producers.\n中间商从生产者那里攫取利润。\n\n② The business was being leeched by hidden fees.\n这家企业的收益被隐藏收费不断蚕食。"},{"kind":"phrase","front":"ramshackle","meaning":"摇摇欲坠的；草率拼凑的","example":"① They lived in a ramshackle house.\n他们住在一栋破旧摇晃的房子里。\n\n② The party was a ramshackle coalition.\n这个政党是一个松散拼凑的联盟。"},{"kind":"phrase","front":"strain under","meaning":"承受……的巨大压力","example":"① The system strained under heavy demand.\n系统因需求过大而承受压力。\n\n② The coalition was straining under internal divisions.\n联盟因内部纷争而难以维持。"},{"kind":"phrase","front":"anarchy and upheaval","meaning":"无政府状态与动荡","example":"① The collapse triggered anarchy and upheaval.\n这场崩溃引发无政府状态和动荡。\n\n② Opponents warned of anarchy and upheaval.\n反对者警告可能出现混乱与剧变。"},{"kind":"phrase","front":"lambaste","meaning":"痛斥；猛烈抨击","example":"① The newspaper lambasted the proposal.\n报纸猛烈抨击了这项提案。\n\n② Critics lambasted the government's response.\n批评者痛斥政府的应对。"},{"kind":"phrase","front":"gigantic vagrant","meaning":"身材巨大的流浪者；gigantic=巨大的，vagrant=流浪者","example":"① The cartoon depicted a gigantic vagrant.\n漫画描绘了一个巨大的流浪者。\n\n② A vagrant slept near the station entrance.\n一名流浪者睡在车站入口附近。"},{"kind":"phrase","front":"leap from obscurity","meaning":"从默默无闻一跃成名","example":"① The writer leapt from obscurity to fame.\n这位作家从默默无闻一跃成名。\n\n② One successful film helped him leap from obscurity.\n一部成功影片助他突然走红。"},{"kind":"phrase","front":"forthcoming","meaning":"即将到来的；愿意提供信息的；（证据等）出现","example":"① No evidence was forthcoming.\n始终没有证据出现。\n\n② She was forthcoming about the difficulties.\n她坦诚地说明了困难。"},{"kind":"phrase","front":"comrade","meaning":"同志；同伴；战友","example":"① He disagreed with his former comrades.\n他与昔日同志意见相左。\n\n② The veterans remembered their fallen comrades.\n老兵们怀念牺牲的战友。"},{"kind":"phrase","front":"ripple through the city","meaning":"消息、影响传遍全城","example":"① News of the resignation rippled through the city.\n辞职消息传遍全城。\n\n② The shock rippled through the city within hours.\n数小时内震动波及整个城市。"},{"kind":"phrase","front":"cavernous","meaning":"巨大而空旷的（室内空间）","example":"① The event took place in a cavernous hall.\n活动在一座巨大空旷的大厅举行。\n\n② Their new warehouse was cavernous.\n他们的新仓库内部十分宽敞。"},{"kind":"phrase","front":"sobbing","meaning":"啜泣的；抽噎的","example":"① Sobbing relatives gathered outside.\n抽泣的亲属聚集在外面。\n\n② She was sobbing after hearing the news.\n听到消息后她不停抽泣。"},{"kind":"phrase","front":"contagious","meaning":"传染性的；（情绪、笑声）有感染力的","example":"① Her laughter was contagious.\n她的笑声很有感染力。\n\n② The illness is highly contagious.\n这种疾病传染性很强。"},{"kind":"phrase","front":"outstrip and outlast","meaning":"超过……并比……持续更久","example":"① His influence outstripped and outlasted his career.\n他的影响力超越了职业成就，且持续更久。\n\n② Demand outstripped supply, and the shortage outlasted the winter.\n需求超过供应，短缺一直持续到冬季之后。"},{"kind":"phrase","front":"sprout across","meaning":"在各地迅速涌现、遍地出现","example":"① New cafes sprouted across the city.\n新咖啡馆在全城涌现。\n\n② Small political clubs sprouted across the country.\n小型政治俱乐部在全国各地出现。"},{"kind":"phrase","front":"fanatically","meaning":"狂热地；极端执着地","example":"① The group was fanatically devoted to the cause.\n这个团体狂热地投入这项事业。\n\n② He followed the rules almost fanatically.\n他近乎偏执地遵守规则。"},{"kind":"phrase","front":"rudimentary","meaning":"初步的；简陋的；基础的","example":"① The village had only rudimentary facilities.\n村庄只有简陋的设施。\n\n② I have a rudimentary understanding of the language.\n我对这门语言只有初步了解。"},{"kind":"phrase","front":"disenfranchised","meaning":"被剥夺投票权的；被排除在决策之外的","example":"① Many residents felt disenfranchised.\n许多居民觉得自己被剥夺了参与权。\n\n② The reform aimed to include previously disenfranchised voters.\n改革旨在让此前被剥夺投票权的人参与选举。"},{"kind":"phrase","front":"monument (to) [figurative]","meaning":"对……的纪念物；……的象征性遗产","example":"① The game became a monument to his ideas.\n这款游戏成为其思想的纪念物。\n\n② The building is a monument to civic ambition.\n这栋建筑是城市雄心的象征。"},{"kind":"phrase","front":"snap up","meaning":"迅速买下；抢购","example":"① Investors snapped up the cheap properties.\n投资者迅速抢购廉价房产。\n\n② The tickets were snapped up within minutes.\n门票几分钟内就被抢光。"},{"kind":"phrase","front":"prophet","meaning":"先知；预言家；思想先驱（比喻）","example":"① Followers called him a prophet of reform.\n追随者称他为改革的先知。\n\n② He was treated as a prophet of new technology.\n他被视为新技术的预言家。"},{"kind":"phrase","front":"uprising","meaning":"起义；暴动","example":"① The uprising challenged the monarchy.\n起义向君主制发起挑战。\n\n② The army suppressed the uprising.\n军队镇压了起义。"},{"kind":"phrase","front":"falter","meaning":"动摇；衰退；步履维艰","example":"① The economy began to falter.\n经济开始失去动力。\n\n② His voice faltered during the speech.\n演讲时他的声音颤抖了。"},{"kind":"phrase","front":"overthrow","meaning":"推翻（政府、制度）","example":"① The rebels sought to overthrow the regime.\n叛军试图推翻该政权。\n\n② The revolution overthrew the monarchy.\n革命推翻了君主制。"},{"kind":"phrase","front":"coalesce","meaning":"聚合；逐渐形成清晰整体","example":"① Several groups coalesced into a movement.\n几个团体逐渐汇聚成一场运动。\n\n② Her ideas began to coalesce into a clear plan.\n她的想法逐渐形成一项明确计划。"},{"kind":"phrase","front":"proponent","meaning":"支持者；倡导者","example":"① He was a proponent of land reform.\n他是土地改革的倡导者。\n\n② Proponents say the policy will lower costs.\n支持者认为该政策将降低成本。"},{"kind":"phrase","front":"animate","meaning":"激发；赋予活力；推动（讨论、运动）","example":"① The debate animated the reform movement.\n这场辩论激发了改革运动。\n\n② A sense of justice animated her work.\n正义感推动着她的工作。"},{"kind":"phrase","front":"crest","meaning":"达到顶峰（浪潮、趋势）；浪峰","example":"① Public enthusiasm was cresting.\n公众热情正达到高峰。\n\n② The wave crested just before reaching shore.\n海浪在抵达岸边前形成浪峰。"},{"kind":"phrase","front":"titan","meaning":"巨头；极具影响力的人物｜用法：常见用法：business titan、industry titan、political titan。","example":"① The former engineer became a titan of the technology industry.\n这位前工程师成为科技行业的巨头。\n\n② Few expected the young reformer to become a political titan.\n几乎没人预料这位年轻改革者会成为政坛巨擘。"},{"kind":"phrase","front":"repulsive presumption","meaning":"令人反感的自负；令人厌恶的妄自尊大｜用法：repulsive 强烈贬义；presumption 在此为自以为是，不是“推测”。","example":"① His repulsive presumption alienated even his closest supporters.\n他令人反感的自负甚至疏远了最亲密的支持者。\n\n② The editorial condemned the executive's repulsive presumption.\n社论谴责了这位高管令人厌恶的自大。"},{"kind":"phrase","front":"grouse","meaning":"抱怨；发牢骚｜用法：grouse about sth；语气偏口语，常暗示反复抱怨。","example":"① Investors groused about the company's lack of transparency.\n投资者抱怨公司缺乏透明度。\n\n② Passengers groused about another delayed train.\n乘客们抱怨火车再次晚点。"},{"kind":"phrase","front":"outrage","meaning":"激怒；使义愤填膺｜用法：be outraged by/at sth；作名词可表示公愤。","example":"① The sudden tax increase outraged small business owners.\n突然加税激怒了小企业主。\n\n② Residents were outraged by the decision to sell public land.\n出售公共土地的决定令居民愤怒。"},{"kind":"phrase","front":"steadfastly","meaning":"坚定不移地；毫不动摇地｜用法：steadfastly support / oppose / refuse。","example":"① She steadfastly opposed the sale of the public park.\n她坚决反对出售公共公园。\n\n② The central bank steadfastly defended its inflation target.\n中央银行坚定维护其通胀目标。"},{"kind":"phrase","front":"effusive","meaning":"热情洋溢的；过分热情的｜用法：effusive praise / thanks；强调情感表达外露。","example":"① The CEO was effusive in his praise of the research team.\n首席执行官对研究团队赞不绝口。\n\n② Her effusive welcome surprised the visiting students.\n她热情洋溢的欢迎让来访学生感到意外。"},{"kind":"phrase","front":"muddlehead","meaning":"糊涂虫；头脑混乱的人｜用法：带贬义的非正式称呼，复数 muddleheads。","example":"① The critic dismissed the theorists as muddleheads.\n这位评论家把那些理论家斥为糊涂虫。\n\n② Calling your opponent a muddlehead does not disprove his argument.\n把对手叫作糊涂虫，并不能驳倒他的论点。"},{"kind":"phrase","front":"prowess","meaning":"高超本领；卓越能力｜用法：analytical prowess / technical prowess / military prowess。","example":"① The firm demonstrated impressive technical prowess.\n这家公司展现了出色的技术实力。\n\n② Analytical prowess matters more than confidence in financial research.\n在金融研究中，分析能力比自信更重要。"},{"kind":"phrase","front":"cobble together","meaning":"匆忙拼凑；勉强凑成｜用法：cobble together a coalition / plan / budget；原文加粗跨词尾，已还原。","example":"① The parties cobbled together a fragile governing coalition.\n各党匆忙拼凑出一个脆弱的执政联盟。\n\n② We cobbled together a budget from several small grants.\n我们用几笔小额拨款勉强凑出了一份预算。"},{"kind":"phrase","front":"messiah","meaning":"救世主；被寄予厚望的拯救者｜用法：宗教本义为弥赛亚；比喻时常带讽刺。","example":"① Some supporters treated the politician as a messiah.\n一些支持者把这位政治人物当作救世主。\n\n② No single investor is a messiah who can predict every downturn.\n没有哪个投资者是能预测每次下跌的救世主。"},{"kind":"phrase","front":"widespread support","meaning":"广泛支持｜用法：gain / enjoy / attract widespread support。","example":"① The proposal gained widespread support among young voters.\n这项提案获得年轻选民广泛支持。\n\n② Public transport improvements enjoy widespread support.\n改善公共交通得到广泛支持。"},{"kind":"phrase","front":"fatally weakened","meaning":"受到致命削弱；元气大伤｜用法：fatally 在此表示足以导致失败，而非必然有人死亡。","example":"① Repeated scandals fatally weakened the governing party.\n接连发生的丑闻使执政党元气大伤。\n\n② The funding cuts fatally weakened the research project.\n资金削减使这项研究项目难以为继。"},{"kind":"phrase","front":"aristocracy","meaning":"贵族阶层；上层精英集团｜用法：原文比喻“全球左翼的统治精英”，不必指世袭贵族。","example":"① The aristocracy retained control of much of the farmland.\n贵族阶层仍控制着大部分农田。\n\n② A new aristocracy of financial insiders emerged.\n一个由金融圈内部人士组成的新精英阶层出现了。"},{"kind":"phrase","front":"backlash","meaning":"强烈反弹；抵制；反对浪潮｜用法：a backlash against sth；face / trigger a backlash。","example":"① The housing policy triggered a public backlash.\n住房政策引发了公众的强烈反弹。\n\n② The company faced a backlash against its price increases.\n这家公司因涨价遭到强烈抵制。"},{"kind":"phrase","front":"in tatters","meaning":"支离破碎；严重受损｜用法：常形容 plans、reputation、economy、political order。","example":"① After the banking crisis, public trust was in tatters.\n银行危机之后，公众信任支离破碎。\n\n② The peace agreement lay in tatters after renewed fighting.\n战火重燃使和平协议几乎化为泡影。"},{"kind":"phrase","front":"in flux","meaning":"处于变化之中；尚未稳定｜用法：常与 politics、markets、industry、situation 连用。","example":"① The energy market is still in flux.\n能源市场仍在不断变化。\n\n② With new laws under discussion, the housing market remains in flux.\n随着新法案进入讨论，住房市场仍处于变动之中。"},{"kind":"phrase","front":"quaint","meaning":"古雅的；老派而略显过时的｜用法：原文带对比和轻微讽刺：过去的担忧现在显得不值一提。","example":"① The old rule now seems rather quaint.\n那条旧规定如今看起来有些过时。\n\n② Their earlier fears appeared quaint after the financial crash.\n金融崩盘之后，他们先前的担忧显得微不足道。"},{"kind":"phrase","front":"sedition","meaning":"煽动叛乱；煽动反政府罪｜用法：法律及政治史用词；sedition charges。","example":"① The activist was charged with sedition by the regime.\n该活动人士被政权指控犯有煽动叛乱罪。\n\n② The historian examined the government's use of sedition laws.\n历史学家研究了政府如何使用煽动叛乱法律。"},{"kind":"phrase","front":"naivety","meaning":"天真；幼稚；缺乏现实判断｜用法：也拼作 naivete / naïveté；political naivety。","example":"① His political naivety left him vulnerable to manipulation.\n他的政治天真让他容易受到操纵。\n\n② Assuming every promise will be kept shows naivety.\n以为每项承诺都会兑现，显得过于天真。"},{"kind":"phrase","front":"turbulent","meaning":"动荡的；剧烈变化的｜用法：turbulent times / markets / period。","example":"① The country entered a turbulent period of reform.\n该国进入了动荡的改革时期。\n\n② Investors reduced leverage during turbulent markets.\n市场剧烈波动时，投资者降低了杠杆。"},{"kind":"phrase","front":"unwittingly","meaning":"无意中；不知不觉地｜用法：常表示并非出于本意，后果可能负面。","example":"① The subsidy unwittingly encouraged land speculation.\n这项补贴无意中刺激了土地投机。\n\n② By sharing the rumor, she unwittingly spread misinformation.\n她转发谣言，无意中传播了错误信息。"},{"kind":"phrase","front":"unintentional launchpad","meaning":"无意间成为的起点；意外跳板｜用法：launchpad for sth 指某事业发展的起点。","example":"① The local newspaper became an unintentional launchpad for his career.\n这家地方报纸无意中成了他职业生涯的跳板。\n\n② A minor policy debate served as an unintentional launchpad for a national movement.\n一场小型政策争论意外成为全国性运动的起点。"},{"kind":"phrase","front":"threshold","meaning":"门槛；临界点｜用法：on the threshold of；cross the threshold。","example":"① The economy stood on the threshold of recovery.\n经济正处于复苏的门槛上。\n\n② The firm crossed the threshold for mandatory disclosure.\n这家公司达到了强制披露的门槛。"},{"kind":"phrase","front":"hamstring","meaning":"严重阻碍；束缚手脚｜用法：hamstrung 为过去式/过去分词；常用 be hamstrung by。","example":"① A shortage of skilled workers hamstrung the expansion.\n熟练工人短缺严重阻碍了扩张。\n\n② The agency was hamstrung by outdated regulations.\n该机构受到过时法规的严重掣肘。"},{"kind":"phrase","front":"usher in","meaning":"开启；引入新时代｜用法：usher in an era / a period of change；原文仅加粗 ushered，按上下文还原搭配。","example":"① The reform ushered in a new era of land policy.\n这项改革开启了土地政策的新时代。\n\n② Cheap credit helped usher in a housing boom.\n廉价信贷助推了住房繁荣的到来。"},{"kind":"phrase","front":"internecine strife","meaning":"内部纷争；内斗｜用法：internecine 特指同一群体内部互相伤害的冲突。","example":"① Internecine strife weakened the ruling coalition.\n内部纷争削弱了执政联盟。\n\n② The party was consumed by internecine strife.\n该党深陷内部斗争。"},{"kind":"phrase","front":"splintered","meaning":"分裂的；四分五裂的｜用法：splintered country / movement；动词 splinter。","example":"① The splintered opposition struggled to unite.\n四分五裂的反对派难以团结。\n\n② A splintered market makes national regulation harder.\n碎片化市场使全国性监管更加困难。"},{"kind":"phrase","front":"horrendous","meaning":"骇人的；极其糟糕的｜用法：horrendous losses / conditions / violence。","example":"① Residents endured horrendous living conditions.\n居民忍受着极其恶劣的生活条件。\n\n② The fund reported horrendous losses after the crash.\n这只基金在崩盘后公布了惨重亏损。"},{"kind":"phrase","front":"enshrine","meaning":"将……庄严写入法律；奉为根本原则｜用法：be enshrined in the constitution / law。","example":"① Equal rights are enshrined in the constitution.\n平等权利被写入宪法。\n\n② The new law enshrines protections for tenants.\n新法律正式确立了对租户的保护。"},{"kind":"phrase","front":"wane","meaning":"衰退；减弱；逐渐消失｜用法：influence / support / power wanes。","example":"① Public enthusiasm for the reform began to wane.\n公众对改革的热情开始减弱。\n\n② The industry's pricing power waned as competition grew.\n随着竞争加剧，该行业的定价权逐渐削弱。"},{"kind":"phrase","front":"hemorrhage","meaning":"大量流失；严重失血｜用法：美式拼法 hemorrhage；英式 haemorrhage；可喻指资金或人才流失。","example":"① The bank continued to hemorrhage deposits.\n这家银行的存款持续大量流失。\n\n② The party hemorrhaged support after the scandal.\n丑闻之后该党支持率急剧流失。"},{"kind":"phrase","front":"cemented in law","meaning":"被正式确立于法律中｜用法：cement 作动词：巩固；cement sth in law。","example":"① The tax exemption was eventually cemented in law.\n这项税收豁免最终被正式写入法律。\n\n② The agreement cemented workers' rights in law.\n协议使工人权利获得了明确法律保障。"},{"kind":"phrase","front":"unravel","meaning":"瓦解；失败；揭开复杂问题｜用法：plans unravel / a coalition unravels；原文过去式 unraveled。","example":"① The coalition began to unravel after the election.\n选举后，这个联盟开始瓦解。\n\n② Their ambitious plan unraveled when funding disappeared.\n资金断裂后，他们雄心勃勃的计划破产了。"},{"kind":"phrase","front":"contentious","meaning":"有争议的；容易引发争论的｜用法：a contentious issue / proposal / debate。","example":"① Land taxation remains a contentious issue.\n土地税仍是一个有争议的问题。\n\n② The committee postponed a vote on the contentious bill.\n委员会推迟了对争议法案的投票。"},{"kind":"phrase","front":"advent","meaning":"到来；出现｜用法：the advent of sth 常见于科技、制度、时代。","example":"① The advent of digital banking changed consumer habits.\n数字银行的出现改变了消费者习惯。\n\n② The advent of universal suffrage reshaped party politics.\n普选权的到来重塑了政党政治。"},{"kind":"phrase","front":"gales","meaning":"大风；狂风；强烈冲击（比喻）｜用法：原文政治风暴比喻；gale-force winds。","example":"① The coastal town was hit by powerful gales.\n这个海滨城镇遭到强风袭击。\n\n② The new government faced gales of criticism.\n新政府遭遇了猛烈的批评。"},{"kind":"phrase","front":"enfranchised","meaning":"获得投票权的｜用法：enfranchise sb / newly enfranchised voters。","example":"① Newly enfranchised voters changed the election outcome.\n新获得投票权的选民改变了选举结果。\n\n② The reform enfranchised millions of citizens.\n这项改革赋予数百万公民选举权。"},{"kind":"phrase","front":"zenith","meaning":"顶点；鼎盛时期｜用法：reach one's zenith / at its zenith；反义 nadir。","example":"① Private construction reached its zenith in the 1930s.\n私人住宅建设在 20 世纪 30 年代达到顶峰。\n\n② The movement was at its zenith before the war.\n这场运动在战前处于鼎盛时期。"},{"kind":"phrase","front":"afoot","meaning":"正在进行中的；即将发生的｜用法：something is afoot；通常置于系动词后。","example":"① Major changes are afoot in the housing market.\n住房市场正在发生重大变化。\n\n② With new rules under discussion, reform is clearly afoot.\n新规则正在讨论，显然改革已在酝酿。"},{"kind":"phrase","front":"swathes","meaning":"大片区域；大量｜用法：英式 swathes；美式 swaths；huge swathes of land。","example":"① The railway opened up huge swathes of rural land.\n铁路开发使大片农村土地得以利用。\n\n② Rising rents affected large swathes of the city.\n租金上涨影响了城市的大部分地区。"},{"kind":"phrase","front":"paired with","meaning":"与……相结合；加上｜用法：常见于原因、条件、政策和产品搭配。","example":"① Lower rates, paired with subsidies, boosted demand.\n较低利率加上补贴刺激了需求。\n\n② Clear rules paired with better data can improve lending decisions.\n清晰规则结合更好的数据能改善贷款决策。"},{"kind":"phrase","front":"affinity","meaning":"亲近感；相似性；天然联系｜用法：an affinity with / for sth；也可指化学亲和力。","example":"① Homeowners developed a stronger affinity with the party.\n房主对该党产生了更强的认同感。\n\n② She has a natural affinity for languages.\n她天生对语言有亲近感。"},{"kind":"phrase","front":"bulwark","meaning":"防线；堡垒；保护力量｜用法：a bulwark against sth。","example":"① Independent courts are a bulwark against arbitrary power.\n独立法院是抵御任意权力的防线。\n\n② A diversified portfolio can serve as a bulwark against volatility.\n分散的投资组合能成为抵御波动的一道防线。"},{"kind":"phrase","front":"gentry","meaning":"乡绅阶层；有产乡绅｜用法：the landed gentry；集合名词，通常不指单个人。","example":"① The landed gentry dominated local politics.\n土地乡绅阶层主导了地方政治。\n\n② The reforms weakened the power of the rural gentry.\n改革削弱了乡村乡绅的权力。"},{"kind":"phrase","front":"illuminate","meaning":"阐明；照亮；揭示｜用法：illuminate a problem / contrast / pattern。","example":"① The report illuminates the link between credit and land prices.\n报告阐明了信贷与土地价格的联系。\n\n② Her example illuminated the weaknesses of the proposal.\n她举的例子揭示了提案的缺陷。"},{"kind":"phrase","front":"hectoring","meaning":"盛气凌人地训斥；咄咄逼人的说教｜用法：hector 可作动词；hectoring tone。","example":"① His hectoring tone alienated potential allies.\n他咄咄逼人的语气疏远了潜在盟友。\n\n② Voters grew tired of the politician's hectoring.\n选民厌倦了这名政治人物的训斥式说教。"},{"kind":"phrase","front":"crankery","meaning":"怪诞固执的想法或行为｜用法：少见贬义词，来自 crank（怪人）；多用于讽刺。","example":"① Critics dismissed the proposal as crankery.\n批评者斥责这项提议是异想天开的怪论。\n\n② Unusual ideas should be tested, not automatically labeled crankery.\n不寻常的观点应该接受检验，而不应自动被称作怪论。"},{"kind":"phrase","front":"proselytizer","meaning":"积极劝人接受某种信仰或主张的人｜用法：proselytize 常有“传教式宣传”意味。","example":"① He was regarded as a political proselytizer rather than a scholar.\n人们更多把他视为政治宣传者，而非学者。\n\n② The energetic proselytizer won supporters for the tax reform.\n这位热情的理念传播者为税制改革争取到了支持者。"},{"kind":"phrase","front":"rump","meaning":"残余部分；规模很小的余部｜用法：政治语境 rump party / rump faction。","example":"① After the split, only a rump of the original party remained.\n分裂后原党只剩下一小部分残余力量。\n\n② The movement was reduced to a political rump.\n这场运动缩减为微不足道的政治余部。"},{"kind":"phrase","front":"diluted into the pottage of","meaning":"融入一锅大杂烩而失去特色｜用法：作者刻意使用比喻；pottage 原指稠汤，整体不是常见固定搭配。","example":"① The small party was diluted into the pottage of a broader coalition.\n这个小党派融入更大的联盟后失去了自身特色。\n\n② Her distinctive proposal was diluted into a vague package of reforms.\n她原本鲜明的提案被稀释进一套模糊的改革方案。"},{"kind":"phrase","front":"ardent","meaning":"热忱的；坚定的；强烈的｜用法：ardent supporter / advocate / admirer。","example":"① She remained an ardent supporter of land reform.\n她始终是土地改革的坚定支持者。\n\n② An ardent debate followed the announcement.\n公告发布后掀起了激烈讨论。"},{"kind":"phrase","front":"go far beyond","meaning":"远远超出；不只涉及｜用法：go far beyond sth；原文 went far beyond。","example":"① The consequences go far beyond the housing market.\n后果远不止影响住房市场。\n\n② His research went far beyond the original question.\n他的研究远远超出了最初的问题。"},{"kind":"phrase","front":"enamored with","meaning":"迷恋；对……着迷｜用法：enamored of/with 均可；原文在该处加粗。","example":"① Investors became enamored with the new technology.\n投资者对这项新技术十分着迷。\n\n② The party was once enamored with the reformer's ideas.\n该党曾深受这位改革者思想的吸引。"},{"kind":"phrase","front":"slum","meaning":"贫民窟；贫民区｜用法：slum housing / slum landlord；通常带负面社会含义。","example":"① The city launched a program to improve slum housing.\n该市启动了改善贫民窟住房的计划。\n\n② Families were trapped in overcrowded slum districts.\n家庭被困在拥挤的贫民区。"},{"kind":"phrase","front":"undermine","meaning":"削弱；损害；暗中破坏｜用法：undermine confidence / authority / principle；原文仅高亮了词内后半段，已还原全词。","example":"① Unclear rules can undermine investor confidence.\n不明确的规则可能削弱投资者信心。\n\n② The policy inadvertently undermined its own goals.\n该政策无意中损害了自身目标。"},{"kind":"phrase","front":"entrench","meaning":"使根深蒂固；进一步巩固｜用法：entrench inequality / privilege / power。","example":"① The subsidy entrenched existing inequalities.\n补贴进一步固化了既有不平等。\n\n② New regulations may entrench the market leaders' advantage.\n新规可能进一步巩固市场龙头的优势。"},{"kind":"phrase","front":"impetus","meaning":"推动力；刺激因素；动力｜用法：give impetus to / provide an impetus for。","example":"① The crisis provided fresh impetus for financial reform.\n危机为金融改革提供了新的动力。\n\n② Lower borrowing costs gave impetus to construction.\n更低的借款成本推动了建筑业发展。"},{"kind":"phrase","front":"febrile","meaning":"紧张激烈的；躁动不安的；发热的｜用法：febrile atmosphere / markets / industrial relations。","example":"① A febrile political atmosphere preceded the election.\n选举前政治气氛十分紧张。\n\n② Speculation created a febrile mood in property markets.\n投机使房地产市场情绪异常躁动。"},{"kind":"phrase","front":"net","meaning":"净赚；获得（收益）｜用法：net a profit / net millions；名词 net 另有“网”。","example":"① The developer netted a large profit from the land sale.\n开发商通过出售土地净赚了一大笔钱。\n\n② The investment netted a return of eight percent after fees.\n扣除费用后，这项投资获得了 8%的收益。"},{"kind":"phrase","front":"auctioneer","meaning":"拍卖师；拍卖商｜用法：auctioneer 指主持/组织拍卖的人；复数 auctioneers。","example":"① The auctioneer opened the bidding at one million euros.\n拍卖师以一百万欧元开始竞价。\n\n② Several auctioneers competed to sell the historic estate.\n几家拍卖机构争夺这处历史地产的销售业务。"},{"kind":"phrase","front":"on bail","meaning":"处于保释期间｜用法：release sb on bail / be out on bail。","example":"① The businessman remained on bail pending trial.\n这名商人在等待审判期间仍处于保释状态。\n\n② She was released on bail after the hearing.\n听证会后她获准保释。"},{"kind":"phrase","front":"eponymous","meaning":"以某人名字命名的；同名的｜用法：eponymous novel / character；原文指以 Ponzi 命名的骗局。","example":"① The Ponzi scheme takes its name from its eponymous fraudster.\n庞氏骗局以那位同名诈骗犯命名。\n\n② The novel's eponymous hero appears in the first chapter.\n这部小说的同名主人公在第一章出现。"},{"kind":"phrase","front":"swindle","meaning":"诈骗；骗取｜用法：swindle sb out of money；swindle 作名词亦可。","example":"① The fraudster swindled investors out of their savings.\n诈骗犯骗走了投资者的积蓄。\n\n② The company was accused of swindling customers.\n这家公司被指控诈骗客户。"},{"kind":"phrase","front":"almighty","meaning":"极其巨大的；惊人的；全能的｜用法：原文 almighty crash 表示规模惊人的崩盘，带强调色彩。","example":"① The market suffered an almighty crash after the bubble burst.\n泡沫破裂后，市场遭遇了惊人的崩盘。\n\n② The announcement caused an almighty row in parliament.\n这项公告在议会引发轩然大波。"},{"kind":"phrase","front":"emphatically","meaning":"明确而强烈地；斩钉截铁地｜用法：state / deny / reject emphatically。","example":"① The minister emphatically rejected the allegation.\n部长断然否认这项指控。\n\n② The report emphatically warned against excessive leverage.\n报告明确而强烈地警告不要过度加杠杆。"},{"kind":"phrase","front":"relegate","meaning":"使降级；使处于次要地位｜用法：relegate sth to a secondary role / position。","example":"① The issue was relegated to the bottom of the agenda.\n这个问题被放到了议程末尾。\n\n② Land was relegated to a secondary role in economic theory.\n土地在经济理论中被降为次要角色。"},{"kind":"phrase","front":"patchy and varied","meaning":"参差不齐且差异较大；不均衡｜用法：patchy coverage / patchy availability；原文合并两个形容词。","example":"① Mortgage access was patchy and varied across regions.\n各地区抵押贷款的可获得性参差不齐。\n\n② The quality of the available data is patchy and varied.\n现有数据质量不均衡、差异较大。"},{"kind":"phrase","front":"aversion","meaning":"厌恶；强烈排斥｜用法：an aversion to sth；risk aversion 为“风险厌恶”。","example":"① Banks once had an aversion to long-term mortgage lending.\n银行过去曾排斥长期抵押贷款。\n\n② Risk aversion often rises during financial crises.\n金融危机期间风险厌恶情绪往往上升。"},{"kind":"phrase","front":"incense","meaning":"激怒；使极度愤慨｜用法：原文 incensed 是过去分词；与 incense（熏香）同形不同义。","example":"① The restrictions incensed colonial merchants.\n这些限制激怒了殖民地商人。\n\n② Residents were incensed by the unfair property tax.\n不公平的房产税使居民极为愤怒。"},{"kind":"phrase","front":"cohort","meaning":"同一批人；具有共同特征的群体｜用法：a cohort of homeowners / students / customers。","example":"① A new cohort of homeowners entered the market.\n新一批房主进入市场。\n\n② Researchers tracked a cohort of borrowers over ten years.\n研究人员跟踪了一批借款人十年。"},{"kind":"phrase","front":"confluence","meaning":"汇合；多种因素共同作用｜用法：the confluence of A, B and C。","example":"① A confluence of cheap credit and subsidies fueled demand.\n低成本信贷与补贴等因素共同推动了需求。\n\n② The crisis resulted from a confluence of economic pressures.\n危机由多种经济压力共同造成。"},{"kind":"phrase","front":"incentivize","meaning":"激励；通过措施促使｜用法：incentivize investment / innovation / homeownership。","example":"① Tax relief can incentivize long-term investment.\n税收减免可以激励长期投资。\n\n② The program incentivized first-time homebuyers.\n该计划鼓励首次购房者买房。"},{"kind":"phrase","front":"moribund","meaning":"濒临消亡的；停滞衰败的｜用法：moribund industry / economy / market。","example":"① Low demand left the construction industry moribund.\n需求低迷使建筑业陷入停滞。\n\n② The reforms revived a moribund regional economy.\n改革使一个衰败的地区经济恢复了活力。"},{"kind":"phrase","front":"a barrage of new programs","meaning":"一连串密集推出的新计划｜用法：a barrage of criticism / questions / measures；强调数量大且接连不断。","example":"① The government announced a barrage of new housing programs.\n政府密集推出了一系列新住房计划。\n\n② The minister faced a barrage of difficult questions.\n部长遭到一连串尖锐提问。"},{"kind":"phrase","front":"severity","meaning":"严重程度；严峻性｜用法：the severity of a crisis / recession / illness。","example":"① Policymakers underestimated the severity of the recession.\n政策制定者低估了经济衰退的严重程度。\n\n② The report assessed the severity of the housing shortage.\n报告评估了住房短缺的严重程度。"},{"kind":"phrase","front":"reams","meaning":"大量（文件、纸张、资料）｜用法：reams of paperwork / documents / legislation；原义“一令纸”。","example":"① The committee reviewed reams of financial documents.\n委员会审阅了大量财务文件。\n\n② New regulations generated reams of paperwork.\n新规产生了大量文书工作。"},{"kind":"phrase","front":"foster","meaning":"促进；培育；扶持｜用法：foster growth / trust / innovation / cooperation。","example":"① The new rules helped foster competition.\n新规则有助于促进竞争。\n\n② Cheap mortgages fostered a boom in homeownership.\n低成本抵押贷款推动了住房自有的繁荣。"},{"kind":"phrase","front":"vanishingly","meaning":"极其；微乎其微地｜用法：vanishingly small / rare / few。","example":"① The probability of default appeared vanishingly small.\n违约概率看起来微乎其微。\n\n② Vanishingly few households qualified for the old tax benefit.\n符合旧税收优惠条件的家庭极少。"},{"kind":"phrase","front":"matter enormously","meaning":"极其重要；产生重大影响｜用法：matter enormously to sb / for sth；由整句加粗拆解。","example":"① Mortgage rates matter enormously to first-time buyers.\n抵押贷款利率对首次购房者极其重要。\n\n② Data quality matters enormously for reliable backtesting.\n数据质量对可靠的回测极其重要。"},{"kind":"phrase","front":"continue to roll in","meaning":"持续不断地涌入；接踵而至｜用法：benefits / orders / donations / applications roll in；由整句加粗拆解。","example":"① Applications continued to roll in after the announcement.\n公告发布后申请不断涌入。\n\n② New benefits for homeowners continued to roll in.\n面向房主的新福利接连出台。"},{"kind":"phrase","front":"stack up","meaning":"不断累积；叠加；经得起比较｜用法：costs / incentives / benefits stack up；原文 stacking up。","example":"① Small fees can stack up over time.\n小额费用会随着时间不断累积。\n\n② The advantages of homeownership began to stack up.\n拥有住房的各种优势开始不断叠加。"},{"kind":"phrase","front":"preferential treatment","meaning":"优惠待遇；特殊优待｜用法：receive / enjoy / grant preferential treatment。","example":"① Homeowners received preferential tax treatment.\n房主享受了税收优惠待遇。\n\n② The policy gave certain borrowers preferential treatment.\n这项政策给予部分借款人特殊优待。"},{"kind":"phrase","front":"ebb away","meaning":"逐渐消退；慢慢减弱｜用法：enthusiasm / influence / support ebbs away；原文 ebbed away。","example":"① Public enthusiasm for the campaign slowly ebbed away.\n公众对这场运动的热情逐渐消退。\n\n② The movement's political influence ebbed away after the war.\n战后这场运动的政治影响力慢慢消失。"}];
